/** One changed section (hunk) of a file. */
export interface CodeDiffChange {
  /** The section's lines: added, removed and unchanged context. */
  diff: CodeDiffChangeLine[];
  /** Where the section is, as git writes it between `@@` markers, for example `-12,7 +12,9`. */
  header: string;
}

/** One line of a changed section. */
export interface CodeDiffChangeLine {
  /** Whether the line was added, removed or left unchanged. */
  type: CodeDiffChangeLineType;
  /** The line's text, without the leading `+` or `-`. */
  text: string;
}

/** One changed file in a diff. */
export interface CodeDiffFile {
  /** The file's old mode (for example `100644`), when it was deleted or its mode changed. */
  fileModeOld: string | null;
  /** The file's new mode (for example `100755`), when it is new or its mode changed. */
  fileModeNew: string | null;
  /** The path the file was renamed or copied from. */
  pathOld: string | null;
  /** The path the file was renamed or copied to. */
  pathNew: string | null;
  /** Whether the file was renamed. */
  isRenamed: boolean;
  /** Whether the file was deleted. */
  isDeleted: boolean;
  /** Whether the file is new. */
  isNew: boolean;
  /** Whether the file was copied from another. */
  isCopied: boolean;
  /** For a rename or copy, how similar the two files are, as a percentage. */
  similarityIndex: number | null;
  /** For a rewritten file, how different the old and new contents are, as a percentage. */
  dissimilarityIndex: number | null;
  /** The git object id (abbreviated) of the file's old contents. */
  hashOld: string | null;
  /** The git object id (abbreviated) of the file's new contents. */
  hashNew: string | null;
  /** The file's path within its repository. */
  filename: string | null;
  /** The changed sections of the file. Empty for a binary file. */
  changes: CodeDiffChange[];
  /** Whether the file is binary, so no line changes are given. */
  isBinary: boolean;
  /** The `name` of the run repository the file is in. */
  repositoryName: string | null;
}

/** A code pipeline: a recipe for AI coding agents to work on your git repositories in phases and steps. Each deploy adds a version; a run uses the newest enabled one. */
export interface CodePipeline {
  /** The pipeline's name, unique within its namespace. */
  name: string;
  /** Every version of the pipeline's definition, oldest first. */
  versions: CodePipelineVersion[];
  /**
   * The id of the user who created it. A call made with an API key is recorded as the key's user.
   *
   * Format: uuid.
   */
  userCreatedById: string;
  /**
   * The id of the namespace it belongs to.
   *
   * Format: uuid.
   */
  namespaceId: string;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** An AI coding agent in a code pipeline: the engine (coding tool) and model it runs on, its instructions, and the tools it may use. */
export interface CodePipelineAgent {
  /** The agent's name, unique within the pipeline. Steps and agent overrides refer to the agent by it. */
  name: string;
  /** The engine (coding tool) the agent runs on. A run can switch it with `agentOverrides`. */
  defaultEngine: CodeEngineType;
  /** The agent's role. A step can name a role instead of an agent (`targetRole`) and run on any agent with it. Null: the agent can only be chosen by name. */
  role: CodePipelineAgentRole | null;
  /** Free-form capability tags. A step can name tags (`targetTags`) and run on any agent carrying at least one of them, ignoring case. */
  tags: string[] | null;
  /** The model the agent uses, as the engine names it. Null: the engine's default model. A run can switch it with `agentOverrides`. */
  defaultModel: string | null;
  /** The agent's own system prompts, combined with the pipeline's as `systemPromptMode` says. */
  systemPrompts: string[] | null;
  /** Extra prompts used only when the agent runs on a particular engine, added after its `systemPrompts`. */
  enginePrompts: CodePipelineAgentEnginePrompt[] | null;
  /** How the agent's `systemPrompts` combine with the pipeline's: `Additional` (the default) adds them after the pipeline's, `Override` uses only the agent's. */
  systemPromptMode: CodePipelineSystemPromptMode | null;
  /** MCP tools this agent may use, in addition to the pipeline's own. */
  externalOperationsMcp: McpExternalOperationBinding[] | null;
  /** OpenAPI tools this agent may use, in addition to the pipeline's own. */
  externalOperationsOpenApi: OpenApiExternalOperationBinding[] | null;
  /** Whether this agent gets Maitento's web tools, overriding the pipeline's `allowWebTools`. Null: as the pipeline says. */
  allowWebTools: boolean | null;
}

/**
 * An AI coding agent in a code pipeline: the engine (coding tool) and model it runs on, its instructions, and the tools it may use.
 *
 * Request shape of `CodePipelineAgent`: includes the write-only fields the server never returns.
 */
export interface CodePipelineAgentInput {
  /** The agent's name, unique within the pipeline. Steps and agent overrides refer to the agent by it. */
  name?: string;
  /** The engine (coding tool) the agent runs on. A run can switch it with `agentOverrides`. */
  defaultEngine?: CodeEngineType;
  /** The agent's role. A step can name a role instead of an agent (`targetRole`) and run on any agent with it. Null: the agent can only be chosen by name. */
  role?: CodePipelineAgentRole | null;
  /** Free-form capability tags. A step can name tags (`targetTags`) and run on any agent carrying at least one of them, ignoring case. */
  tags?: string[] | null;
  /** The model the agent uses, as the engine names it. Null: the engine's default model. A run can switch it with `agentOverrides`. */
  defaultModel?: string | null;
  /**
   * The agent's own system prompts, combined with the pipeline's as `systemPromptMode` says.
   *
   * Sent as-is: the server does not trim it.
   */
  systemPrompts?: string[] | null;
  /** Extra prompts used only when the agent runs on a particular engine, added after its `systemPrompts`. */
  enginePrompts?: CodePipelineAgentEnginePromptInput[] | null;
  /** How the agent's `systemPrompts` combine with the pipeline's: `Additional` (the default) adds them after the pipeline's, `Override` uses only the agent's. */
  systemPromptMode?: CodePipelineSystemPromptMode | null;
  /** MCP tools this agent may use, in addition to the pipeline's own. */
  externalOperationsMcp?: McpExternalOperationBindingInput[] | null;
  /** OpenAPI tools this agent may use, in addition to the pipeline's own. */
  externalOperationsOpenApi?: OpenApiExternalOperationBindingInput[] | null;
  /** Whether this agent gets Maitento's web tools, overriding the pipeline's `allowWebTools`. Null: as the pipeline says. */
  allowWebTools?: boolean | null;
}

/** Extra system prompts for an agent that apply only when it runs on one engine, so its instructions can be tuned to each coding tool. */
export interface CodePipelineAgentEnginePrompt {
  /** The engine these prompts apply to. */
  engine: CodeEngineType;
  /** The prompts, added after the agent's own `systemPrompts`. */
  prompts: string[];
}

/**
 * Extra system prompts for an agent that apply only when it runs on one engine, so its instructions can be tuned to each coding tool.
 *
 * Request shape of `CodePipelineAgentEnginePrompt`: includes the write-only fields the server never returns.
 */
export interface CodePipelineAgentEnginePromptInput {
  /** The engine these prompts apply to. */
  engine?: CodeEngineType;
  /**
   * The prompts, added after the agent's own `systemPrompts`.
   *
   * Sent as-is: the server does not trim it.
   */
  prompts?: string[];
}

/** An API key for a code pipeline engine, with where its traffic goes. */
export interface CodePipelineApiKeyCredentials {
  /** Discriminator: always `"apiKey"` for this type; send it as the first property. */
  type: "apiKey";
  /** The endpoint to send this key's requests to, for providers that give each key its own host (for example Qwen's regional endpoints). Null: the engine's default endpoint. */
  baseUrl: string | null;
  /** Where the key's model is hosted: `Direct`, `CustomEndpoint`, `AzureFoundry`, `Bedrock` or `Vertex` (see `CodePipelineHostingMode`). Null: `Direct`. */
  hostingMode: string | null;
  /**
   * `hostingMode` as an enum value: `Direct` when it is null or not recognised.
   *
   * Computed by the server; ignored on input.
   */
  readonly parsedHostingMode: CodePipelineHostingMode;
  /** The model id this key needs for each model name (for example a deployment name on Azure), keyed by the model name the agent asks for. Null or empty: model names are used as they are. */
  modelNameOverrides: Record<string, string> | null;
  /** The one model this key serves. Null: any model of its engine. Set it for your own endpoint, so an agent asking for a different model never gets this endpoint. */
  boundModel: string | null;
  /** The context window of `boundModel`, in tokens, for a model the coding tool doesn't know. Null for the built-in engines' models. */
  contextWindowTokens: number | null;
  /** The AWS region, when `hostingMode` is `Bedrock`. */
  awsRegion: string | null;
  /** The Google Cloud project id, when `hostingMode` is `Vertex`. */
  gcpProjectId: string | null;
  /** The Google Cloud region, when `hostingMode` is `Vertex`. */
  gcpRegion: string | null;
  /** The engine this credential is for. */
  engine: CodeEngineType;
  /** Your id for this credential. The run records it on the tokens the credential used (`tokenUsage`) and, when your own credential fails, in `credentialFailures`, so you can tell which key did what. */
  credentialId: string | null;
  /** True for your own key or sign-in, which you pay the provider for. False marks a fallback to Maitento's own key: leave its `apiKey` empty. Its use counts as platform usage, and your tenant can forbid it. */
  isOwnLicense: boolean;
  /** The order to try this engine's credentials in: lower first. Null: after the numbered ones. */
  priority: number | null;
  /** The kind of plan the credential is on with its provider (for example `SubscriptionPlan` or `PayAsYouGoApi`), recorded for reporting. Null when not given. */
  billingMode: string | null;
}

/**
 * An API key for a code pipeline engine, with where its traffic goes.
 *
 * Request shape of `CodePipelineApiKeyCredentials`: includes the write-only fields the server never returns.
 */
export interface CodePipelineApiKeyCredentialsInput {
  /** Discriminator: always `"apiKey"` for this type; send it as the first property. */
  type: "apiKey";
  /**
   * The key. Leave it empty on Maitento's own fallback entry (`isOwnLicense` false).
   *
   * Write-only: accepted on input, never returned by the server.
   */
  apiKey?: string;
  /** The endpoint to send this key's requests to, for providers that give each key its own host (for example Qwen's regional endpoints). Null: the engine's default endpoint. */
  baseUrl?: string | null;
  /** Where the key's model is hosted: `Direct`, `CustomEndpoint`, `AzureFoundry`, `Bedrock` or `Vertex` (see `CodePipelineHostingMode`). Null: `Direct`. */
  hostingMode?: string | null;
  /** The model id this key needs for each model name (for example a deployment name on Azure), keyed by the model name the agent asks for. Null or empty: model names are used as they are. */
  modelNameOverrides?: Record<string, string> | null;
  /** The one model this key serves. Null: any model of its engine. Set it for your own endpoint, so an agent asking for a different model never gets this endpoint. */
  boundModel?: string | null;
  /** The context window of `boundModel`, in tokens, for a model the coding tool doesn't know. Null for the built-in engines' models. */
  contextWindowTokens?: number | null;
  /** The AWS region, when `hostingMode` is `Bedrock`. */
  awsRegion?: string | null;
  /** The Google Cloud project id, when `hostingMode` is `Vertex`. */
  gcpProjectId?: string | null;
  /** The Google Cloud region, when `hostingMode` is `Vertex`. */
  gcpRegion?: string | null;
  /** The engine this credential is for. */
  engine?: CodeEngineType;
  /** Your id for this credential. The run records it on the tokens the credential used (`tokenUsage`) and, when your own credential fails, in `credentialFailures`, so you can tell which key did what. */
  credentialId?: string | null;
  /** True for your own key or sign-in, which you pay the provider for. False marks a fallback to Maitento's own key: leave its `apiKey` empty. Its use counts as platform usage, and your tenant can forbid it. */
  isOwnLicense?: boolean;
  /** The order to try this engine's credentials in: lower first. Null: after the numbered ones. */
  priority?: number | null;
  /** The kind of plan the credential is on with its provider (for example `SubscriptionPlan` or `PayAsYouGoApi`), recorded for reporting. Null when not given. */
  billingMode?: string | null;
}

/** One round of a step's "is it really done?" check (`runChallengeLoop`): what the agent said about its own work. */
export interface CodePipelineChallengeTurn {
  /** The round's number, starting at 1. */
  turn: number;
  /** Whether the agent said more work was still needed. If so, another round runs. */
  reworkNeeded: boolean;
  /** The risk, from 0 to 100, the agent said remained after this round. */
  remainingRiskPercent: number;
  /** Whether the agent's answer could be read. When false, `reworkNeeded` and `remainingRiskPercent` are cautious placeholders rather than the agent's answer, the agent is asked again, and the round doesn't count towards the result. */
  parsed: boolean;
  /** The concerns the agent still had after this round. May be empty once it is satisfied. */
  outstandingConcerns: string | null;
}

/** A reference to one of a run's tool calls, transcript entries or diffs, which are fetched separately: its id and its revision. If you already hold that id at that revision, your copy is current; otherwise fetch it. */
export interface CodePipelineChildRef {
  /**
   * The id of the tool call, transcript entry or diff.
   *
   * Format: uuid.
   */
  id: string;
  /** Its revision (`rev`) when this reference was written. 0 means unknown: treat your copy as out of date and fetch it again. */
  rev: number;
}

/** A code pipeline's definition, to create a pipeline or add a version to one. Most pipelines are deployed from a project folder instead (`code-pipelines/<name>/pipeline-definition.json`). */
export interface CodePipelineCreateRequest {
  /**
   * The pipeline's name, unique within its namespace. At most 128 characters.
   *
   * Validation: maxLength: 128; required (empty or whitespace-only strings are rejected).
   */
  name: string;
  /**
   * The pipeline's agents. At least one.
   *
   * Validation: minLength: 1; required (empty or whitespace-only strings are rejected).
   */
  agents: CodePipelineAgentInput[];
  /**
   * The pipeline's phases, each a group of steps. At least one.
   *
   * Validation: minLength: 1; required (empty or whitespace-only strings are rejected).
   */
  phases: CodePipelinePhaseDefinitionInput[];
  /** MCP tools every agent of the pipeline may use. */
  externalOperationsMcp?: McpExternalOperationBindingInput[];
  /** OpenAPI tools every agent of the pipeline may use. */
  externalOperationsOpenApi?: OpenApiExternalOperationBindingInput[];
  /** Inputs a run supplies as secrets for the tools' authentication. */
  authenticationSecretInputs?: ConnectorAuthenticationSecretInputInput[];
  /** Inputs a run supplies as values bound into the tools' calls. */
  bindingInputs?: ConnectorBindingInputInput[];
  /** Inputs a run supplies for the step prompts (`%%input:name%%`). */
  promptInputs?: PromptInputInput[];
  /** File systems the pipeline declares for its agents. A run mounts only the file systems in its own `vfsMounts`. */
  vfsBindings?: CodePipelineVfsBindingInput[];
  /**
   * The app that holds the pipeline's hooks (its Cogniscript methods). Null: no hooks.
   *
   * Format: uuid.
   */
  cogniscriptAppId?: string | null;
  /**
   * System prompts every agent of the pipeline gets.
   *
   * Sent as-is: the server does not trim it.
   */
  systemPrompts?: string[] | null;
  /** How the pipeline's `systemPrompts` combine with the ones before them. Null: `Additional`. */
  systemPromptMode?: CodePipelineSystemPromptMode | null;
  /** The namespace of a file system to save the agents' sessions in, so a resumed or restarted run carries on from them. Null: sessions are not saved. */
  resumeVfsNamespace?: string | null;
  /** The name of that file system, within `resumeVfsNamespace`. Null: `default`. */
  resumeVfsName?: string | null;
  /**
   * Not used by code pipeline runs.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarning?: DotNetTimeSpan | null;
  /**
   * The longest any step may run, for steps whose step and phase set no `durationAutoTermination`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination?: DotNetTimeSpan | null;
  /**
   * How long any step may go without activity before it is stopped, for steps whose step and phase set no `durationActivityTimeout`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationActivityTimeout?: DotNetTimeSpan | null;
  /**
   * The longest one hook may run. Null: 30 seconds.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  hookDurationLimit?: DotNetTimeSpan | null;
  /** Not used by code pipeline runs. */
  includeEnvironmentInfo?: boolean;
  /** Whether the agents may stop and ask a person a question. The run then waits in `HumanInteractionRequired` until it is answered. */
  allowHumanInteraction?: boolean;
  /** Whether the pipeline's agents get Maitento's web search and fetch tools. Off by default. */
  allowWebTools?: boolean;
  /** The name of a hook to run when the run hits an infrastructure error, such as a failed clone or push. */
  onErrorHook?: string | null;
  /** The most review-and-fix rounds a hook's fix loop may run. Null: 3. Capped at 5. */
  maxFixIterations?: number | null;
  /** For a fix loop that ends on the agents' own confidence: the confidence, from 0 to 1, at which it stops. Null: 0.8. */
  confidenceThreshold?: number | null;
  /** The most phases hooks may add to one run in total. Null: 24. */
  maxInjectedPhases?: number | null;
  /** How many of a phase's steps may run at once. Null: 6. Between 1 and 16. */
  maxParallelSteps?: number | null;
  /** The credential stack the pipeline's runs use, by id or name, when their start doesn't name one: its API keys and coding-agent sign-ins serve the engines, and Maitento's own keys never do. Null: the namespace's default stack, then your tenant's. */
  credentialStack?: string | null;
}

/** A failure of one of your own credentials during a run. The engine then tries its next credential, if it has one. Use it to spot a key that needs fixing or replacing. */
export interface CodePipelineCredentialFailure {
  /** The `credentialId` of the credential that failed. */
  credentialId: string;
  /** Why it failed: `"Auth"` (the key or sign-in was rejected), `"RateLimit"`, `"Quota"` (its usage limit is used up), `"EndpointModelNotFound"` (its endpoint doesn't serve the model asked for) or `"Endpoint"` (its endpoint answered "not found", usually a mistyped base URL). The last two say nothing about whether the key itself is good. */
  reason: string;
  /** A short description of the failure, from the coding tool's output. */
  detail: string | null;
  /**
   * When it failed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUtc: string;
  /** For a `"RateLimit"` failure, how many seconds the provider said to wait before trying again. Null when it didn't say, and for every other reason. */
  retryAfterSeconds: number | null;
}

/** One call a step made to its coding tool: the exit code and both output streams, recorded whether it succeeded or failed. Read them to find out why a step failed. */
export interface CodePipelineEngineOutput {
  /** The call's number within the step, starting at 1 and counting across every retry and resume. */
  sequence: number;
  /**
   * When the call was made, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUtc: string;
  /** What the call was for: the step's own prompt, the structured-output question, a repair pass, and so on. It tells a failed step apart from a failed side call. */
  purpose: string | null;
  /** The coding tool's exit code. -2147483648 means it was stopped before it exited: see `terminationReason`. */
  returnCode: number;
  /** What the coding tool wrote to standard output. */
  stdOut: string | null;
  /** What the coding tool wrote to standard error. */
  stdErr: string | null;
  /** A failure around the coding tool rather than from it, such as it failing to start or being stopped. */
  internalError: string | null;
  /** Why the coding tool was stopped, when it didn't exit by itself: `"Timeout"`, `"Inactivity"`, `"Cancelled"` or `"EngineLaunchFailure"`. Null when it exited normally. */
  terminationReason: string | null;
  /** Whether `stdOut` or `stdErr` was shortened because it was very large. The start and the end are kept, so the error and any stack trace survive. */
  isTruncated: boolean;
}

/** A git repository a code pipeline run clones and pushes over HTTPS. */
export interface CodePipelineGitHttpRepo {
  /** Discriminator: always `"http"` for this type; send it as the first property. */
  type: "http";
  /** The repository's HTTP(S) URL, for example `https://github.com/org/repo.git`. */
  url: string;
  /** The repository's name, unique within the run. Steps name it in `commitRepoName`. */
  name: string;
  /** Context checkout: runner commit/push operations skip this repository. Legacy descriptors default false. */
  isReadOnly: boolean;
  /** The branch to start from. */
  branchSource: string;
  /** The branch the agents' work is committed and pushed to. It can be the same as `branchSource`. */
  branchWork: string;
  /** A command that runs an MCP server from the repository's checkout, which the agents can then call as tools. Null: none. */
  mcpServer: CodePipelineProcessMcpServer | null;
  /** The commit the work branch was at once the repository was checked out for the current attempt. Null until then. */
  resolvedCommitSha: string | null;
  /** The commit the work branch was at when the run first checked it out. Unlike `resolvedCommitSha` it never changes when the run is resumed, so it is where the run's work began. Set by Maitento; any value you send is ignored. */
  runBaseCommitSha: string | null;
  /** The commit the work branch was at after the run's last successful push: what the run delivered. Null when the run pushed nothing to this repository. */
  finalCommitSha: string | null;
  /**
   * When the last successful push landed, in UTC. Null exactly when `finalCommitSha` is.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateLastCommitUtc: string | null;
}

/**
 * A git repository a code pipeline run clones and pushes over HTTPS.
 *
 * Request shape of `CodePipelineGitHttpRepo`: includes the write-only fields the server never returns.
 */
export interface CodePipelineGitHttpRepoInput {
  /** Discriminator: always `"http"` for this type; send it as the first property. */
  type: "http";
  /** The repository's HTTP(S) URL, for example `https://github.com/org/repo.git`. */
  url?: string;
  /**
   * The user name and password or token to clone and push with, as `user:token` (for example `x-access-token:<token>`). Empty: no credentials.
   *
   * Write-only: accepted on input, never returned by the server.
   */
  credentials?: string;
  /** The repository's name, unique within the run. Steps name it in `commitRepoName`. */
  name?: string;
  /** Context checkout: runner commit/push operations skip this repository. Legacy descriptors default false. */
  isReadOnly?: boolean;
  /** The branch to start from. */
  branchSource?: string;
  /** The branch the agents' work is committed and pushed to. It can be the same as `branchSource`. */
  branchWork?: string;
  /** A command that runs an MCP server from the repository's checkout, which the agents can then call as tools. Null: none. */
  mcpServer?: CodePipelineProcessMcpServerInput | null;
  /** The commit the work branch was at once the repository was checked out for the current attempt. Null until then. */
  resolvedCommitSha?: string | null;
  /** The commit the work branch was at when the run first checked it out. Unlike `resolvedCommitSha` it never changes when the run is resumed, so it is where the run's work began. Set by Maitento; any value you send is ignored. */
  runBaseCommitSha?: string | null;
  /** The commit the work branch was at after the run's last successful push: what the run delivered. Null when the run pushed nothing to this repository. */
  finalCommitSha?: string | null;
  /**
   * When the last successful push landed, in UTC. Null exactly when `finalCommitSha` is.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateLastCommitUtc?: string | null;
}

