/**
 * A git repository a code pipeline run clones and pushes over SSH.
 *
 * Request shape of `CodePipelineGitSshRepo`: includes the write-only fields the server never returns.
 */
export interface CodePipelineGitSshRepoInput {
  /** Discriminator: always `"ssh"` for this type; send it as the first property. */
  type: "ssh";
  /** The repository's SSH address, for example `git@github.com:org/repo.git`. */
  gitAddress?: string;
  /**
   * The private SSH key to clone and push with, base64-encoded. Required.
   *
   * Write-only: accepted on input, never returned by the server.
   * Format: base64.
   */
  gitSshKey?: string;
  /** The repository's name, unique within the run. Steps name it in `commitRepoName`. */
  name?: string;
  /** Context checkout: runner commit/push operations skip this repository. Legacy descriptors default false. */
  isReadOnly?: boolean;
  /** The branch to start from. */
  branchSource?: string;
  /** The branch the agents' work is committed and pushed to. It can be the same as `branchSource`. */
  branchWork?: string;
  /** A command that runs an MCP server from the repository's checkout, which the agents can then call as tools. Null: none. */
  mcpServer?: CodePipelineProcessMcpServerInput | null;
  /** The commit the work branch was at once the repository was checked out for the current attempt. Null until then. */
  resolvedCommitSha?: string | null;
  /** The commit the work branch was at when the run first checked it out. Unlike `resolvedCommitSha` it never changes when the run is resumed, so it is where the run's work began. Set by Maitento; any value you send is ignored. */
  runBaseCommitSha?: string | null;
  /** The commit the work branch was at after the run's last successful push: what the run delivered. Null when the run pushed nothing to this repository. */
  finalCommitSha?: string | null;
  /**
   * When the last successful push landed, in UTC. Null exactly when `finalCommitSha` is.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateLastCommitUtc?: string | null;
}

/** The person who answered an agent's question. */
export interface CodePipelineHumanInteractionAnswerAuthor {
  /**
   * The user's id.
   *
   * Format: uuid.
   */
  userId: string;
  /** The user's name when they answered. */
  name: string;
}

/** A question an agent asked a person during a step. The step, and the run, wait until it is answered. A step can ask several. */
export interface CodePipelineHumanInteractionRequest {
  /**
   * The question's id. Pass it as `requestId` when you answer.
   *
   * Format: uuid.
   */
  id: string;
  /** The agent's question. */
  question: string;
  /** Background the agent gave to help answer the question. */
  context: string | null;
  /**
   * When the agent asked, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRequested: string;
  /** Answers the agent suggests. You can pick one or write your own. */
  suggestedAnswers: CodePipelineHumanInteractionSuggestedAnswer[] | null;
  /** The answer. Null until it is answered. */
  answer: string | null;
  /**
   * When it was answered, in UTC. Null until then.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateAnswered: string | null;
  /** Who answered. Null until it is answered. */
  answerAuthor: CodePipelineHumanInteractionAnswerAuthor | null;
}

/** An answer an agent suggests for its own question. */
export interface CodePipelineHumanInteractionSuggestedAnswer {
  /** The suggested answer. */
  answer: string;
  /** Whether the agent recommends this answer. */
  isRecommended: boolean;
}

/** A coding tool's sign-in (OAuth tokens from a subscription) for a code pipeline engine, used in place of an API key. */
export interface CodePipelineOAuthCredentials {
  /** Discriminator: always `"oauth"` for this type; send it as the first property. */
  type: "oauth";
  /**
   * When the access token expires, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  expiresAt: string;
  /** The scopes the tokens were granted. */
  scopes: string[] | null;
  /** The subscription plan the sign-in belongs to (for example a Claude subscription tier), as the provider names it. */
  oAuthSubscriptionType: string | null;
  /** The engine this credential is for. */
  engine: CodeEngineType;
  /** Your id for this credential. The run records it on the tokens the credential used (`tokenUsage`) and, when your own credential fails, in `credentialFailures`, so you can tell which key did what. */
  credentialId: string | null;
  /** True for your own key or sign-in, which you pay the provider for. False marks a fallback to Maitento's own key: leave its `apiKey` empty. Its use counts as platform usage, and your tenant can forbid it. */
  isOwnLicense: boolean;
  /** The order to try this engine's credentials in: lower first. Null: after the numbered ones. */
  priority: number | null;
  /** The kind of plan the credential is on with its provider (for example `SubscriptionPlan` or `PayAsYouGoApi`), recorded for reporting. Null when not given. */
  billingMode: string | null;
}

/**
 * A coding tool's sign-in (OAuth tokens from a subscription) for a code pipeline engine, used in place of an API key.
 *
 * Request shape of `CodePipelineOAuthCredentials`: includes the write-only fields the server never returns.
 */
export interface CodePipelineOAuthCredentialsInput {
  /** Discriminator: always `"oauth"` for this type; send it as the first property. */
  type: "oauth";
  /**
   * The OAuth access token.
   *
   * Write-only: accepted on input, never returned by the server.
   */
  accessToken?: string;
  /**
   * The OAuth refresh token.
   *
   * Write-only: accepted on input, never returned by the server.
   */
  refreshToken?: string;
  /**
   * The OpenID Connect ID token, for coding tools that need it alongside the access and refresh tokens (Codex does; Claude Code doesn't).
   *
   * Write-only: accepted on input, never returned by the server.
   */
  idToken?: string | null;
  /**
   * When the access token expires, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  expiresAt?: string;
  /** The scopes the tokens were granted. */
  scopes?: string[] | null;
  /** The subscription plan the sign-in belongs to (for example a Claude subscription tier), as the provider names it. */
  oAuthSubscriptionType?: string | null;
  /** The engine this credential is for. */
  engine?: CodeEngineType;
  /** Your id for this credential. The run records it on the tokens the credential used (`tokenUsage`) and, when your own credential fails, in `credentialFailures`, so you can tell which key did what. */
  credentialId?: string | null;
  /** True for your own key or sign-in, which you pay the provider for. False marks a fallback to Maitento's own key: leave its `apiKey` empty. Its use counts as platform usage, and your tenant can forbid it. */
  isOwnLicense?: boolean;
  /** The order to try this engine's credentials in: lower first. Null: after the numbered ones. */
  priority?: number | null;
  /** The kind of plan the credential is on with its provider (for example `SubscriptionPlan` or `PayAsYouGoApi`), recorded for reporting. Null when not given. */
  billingMode?: string | null;
}

/** A file the agents wrote to the run's `output_files/` folder, uploaded to the run's `outputFilesPartitionId` knowledge base. It is uploaded as the run goes, a few seconds after each change, so the list grows and updates while the run is live. */
export interface CodePipelineOutputFile {
  /**
   * The uploaded file's id. It stays the same across versions.
   *
   * Format: uuid.
   */
  id: string;
  /** The file's path within `output_files/`, with forward slashes. */
  fileName: string;
  /** The MD5 checksum of the last version uploaded. */
  checksum: string;
  /** The size of the last version uploaded, in bytes. */
  size: number;
  /** The uploaded file's version, which goes up with each change. */
  version: number;
  /**
   * When the last version was uploaded, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateLastUploadedUtc: string;
}

/** A package an agent installed during the run. */
export interface CodePipelinePackageInstall {
  /** The agent that installed it. */
  agentName: string;
  /** The package manager used: `apt`, `npm`, `pip` or `dotnet`. */
  packageManager: string;
  /** The package's name. */
  packageName: string;
  /**
   * When the agent asked for it, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRequested: string;
  /**
   * When the install finished, in UTC. Null while it is still going.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCompleted: string | null;
  /** Whether the install succeeded. */
  wasSuccessful: boolean;
}

/** A phase of a code pipeline: a group of steps that runs once the phases it depends on have finished. */
export interface CodePipelinePhaseDefinition {
  /** The phase's name, unique within the pipeline. */
  name: string;
  /** The phases that must all finish successfully before this one starts. Null or empty: it can start straight away. */
  dependsOn: string[] | null;
  /** The phase's steps. One agent's steps run one after another, in order; different agents' steps run in parallel unless a step's `dependsOn` says otherwise. */
  steps: CodePipelineStepDefinition[];
  /** The name of a hook (a Cogniscript method in the pipeline's hooks) to run before the phase's steps. */
  preHook: string | null;
  /** The name of a hook to run after all the phase's steps finish. Often used to read step outputs and add phases or steps. */
  postHook: string | null;
  /** The name of a hook to run when the phase fails. It returns JSON with a `decision`: `"continue"` marks the phase skipped and carries on, `"fail"` fails the run as usual. */
  onFailHook: string | null;
  /**
   * Not used by code pipeline runs.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarning: DotNetTimeSpan | null;
  /**
   * The longest any step in this phase may run, for steps that set no `durationAutoTermination` of their own. Null: the pipeline's value applies.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination: DotNetTimeSpan | null;
  /**
   * How long any step in this phase may go without activity before it is stopped, for steps that set no `durationActivityTimeout` of their own. Null: the pipeline's value applies.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationActivityTimeout: DotNetTimeSpan | null;
}

/**
 * A phase of a code pipeline: a group of steps that runs once the phases it depends on have finished.
 *
 * Request shape of `CodePipelinePhaseDefinition`: includes the write-only fields the server never returns.
 */
export interface CodePipelinePhaseDefinitionInput {
  /** The phase's name, unique within the pipeline. */
  name?: string;
  /** The phases that must all finish successfully before this one starts. Null or empty: it can start straight away. */
  dependsOn?: string[] | null;
  /** The phase's steps. One agent's steps run one after another, in order; different agents' steps run in parallel unless a step's `dependsOn` says otherwise. */
  steps?: CodePipelineStepDefinitionInput[];
  /** The name of a hook (a Cogniscript method in the pipeline's hooks) to run before the phase's steps. */
  preHook?: string | null;
  /** The name of a hook to run after all the phase's steps finish. Often used to read step outputs and add phases or steps. */
  postHook?: string | null;
  /** The name of a hook to run when the phase fails. It returns JSON with a `decision`: `"continue"` marks the phase skipped and carries on, `"fail"` fails the run as usual. */
  onFailHook?: string | null;
  /**
   * Not used by code pipeline runs.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarning?: DotNetTimeSpan | null;
  /**
   * The longest any step in this phase may run, for steps that set no `durationAutoTermination` of their own. Null: the pipeline's value applies.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination?: DotNetTimeSpan | null;
  /**
   * How long any step in this phase may go without activity before it is stopped, for steps that set no `durationActivityTimeout` of their own. Null: the pipeline's value applies.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationActivityTimeout?: DotNetTimeSpan | null;
}

/** How one phase of a code pipeline run is going, with its steps. */
export interface CodePipelinePhaseExecution {
  /** The phase's name. */
  phaseName: string;
  /** Where the phase is. */
  status: CodePipelinePhaseExecutionStatus;
  /**
   * When the phase started, in UTC. Null until it starts.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateStart: string | null;
  /**
   * When the phase ended, in UTC. Null until it ends.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateEnd: string | null;
  /** The phase's steps, from the definition plus any added for the run or by hooks. */
  steps: CodePipelineStepExecution[];
  /** Why the phase failed. Null unless it did. */
  failureDetails: string | null;
  /** What the phase's `preHook` returned, as JSON. Null when it has none or returned nothing. */
  hookPreOutput: string | null;
  /** What the phase's `postHook` returned, as JSON. Null when it has none or returned nothing. */
  hookPostOutput: string | null;
}

/** A run of a code pipeline: its status, the repositories it works on, and each phase and step as it goes. */
export interface CodePipelineProcess {
  /** The code pipeline and the version of it the run uses. */
  pipeline: VersionReference;
  /** Where the run is. */
  status: CodePipelineProcessStatus;
  /** Why the run failed. Null unless it did. */
  failureDetails: string | null;
  /** The kind of failure, when the run failed because of its coding tool or model provider: `"Auth"` (a key or sign-in was rejected), `"RateLimit"`, `"Quota"` (a usage limit is used up), `"Transient"` (a temporary provider error), `"Terminal"` (an error retrying won't fix), `"EndpointModelNotFound"` (no credential's endpoint serves the model) or `"Endpoint"` (an endpoint answered "not found"). Null when the run hasn't failed, or failed some other way (a git push, for example): check `status` to tell which. */
  failureReason: string | null;
  /** The values the run was started with, by input name. */
  inputs: NameValuePair[];
  /** The engines and models the run uses in place of its agents' defaults. */
  agentOverrides: CodePipelineProcessAgentOverride[] | null;
  /** Agents added for this run only, alongside the pipeline's own. A restart keeps them. */
  additionalAgents: CodePipelineAgent[] | null;
  /** The run's review panel. Null when it has none. A restart keeps it. */
  reviewPanel: CodePipelineReviewPanel | null;
  /** For this run, how many of a phase's steps may run at once, in place of the pipeline's `maxParallelSteps`. Null: the pipeline's value. Between 1 and 16. */
  maxParallelSteps: number | null;
  /** The credentials the run was given for its engines. Keys and tokens are never returned. */
  credentials: CodePipelineProcessCredentials[];
  /** The credential stack the run uses, as it stood when the run started (no secrets: keys are read live). When set, the engines use only this stack. Null: the run uses the credentials it was given. */
  credentialStack: CredentialStackSnapshot | null;
  /** Failures of your own credentials during the current attempt. Null or empty when there were none. */
  credentialFailures: CodePipelineCredentialFailure[] | null;
  /** The git repositories the run works on. Their credentials are never returned. */
  repos: CodePipelineProcessRepo[];
  /** The file systems mounted for the run's agents. */
  vfsMounts: CodePipelineProcessVfsMount[] | null;
  /** An extra system prompt for this run, applied on top of the pipeline's and agents' prompts. */
  systemPromptOverride: string | null;
  /**
   * Uploaded files the run copies into the agents' `files/` folder before it starts.
   *
   * Format: each uuid.
   */
  inputFileIds: string[] | null;
  /** Each phase of the run, with its steps, as it goes. Hooks can add phases while the run is going. */
  phases: CodePipelinePhaseExecution[];
  /** Steps added to the pipeline's phases for this run only. */
  additionalSteps: CodePipelineProcessAdditionalSteps[] | null;
  /** Phases that hooks added to the run, beyond the pipeline's own. */
  injectedPhases: CodePipelinePhaseDefinition[] | null;
  /** How many phases hooks have added to the run so far, counted against the pipeline's `maxInjectedPhases`. */
  injectedPhaseCount: number | null;
  /** The run's variables: step results stored by `outputVariableName`, and values set by hooks. Step prompts read them as `%%name%%`. */
  variables: NameValuePair[] | null;
  /**
   * For a restarted run, the run it was restarted from. Null for a run started any other way.
   *
   * Format: uuid.
   */
  resumeFromProcessId: string | null;
  /**
   * Not currently used.
   *
   * Format: uuid.
   */
  resumeVfsId: string | null;
  /** The prompt a resume-with-prompt sent to the agent. The step that failed or was interrupted carries on in the same session with this prompt instead of its own. Cleared once the agent has it. */
  resumeContinuationPrompt: string | null;
  /**
   * When a worker first started the run, in UTC. A resume doesn't change it.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateStarted: string | null;
  /**
   * When the run ended, in UTC. Null while it is going, and cleared when it is resumed.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateEnded: string | null;
  /**
   * The total time the run has spent working, across every attempt and resume. Time waiting for a worker or for an answer isn't counted. While the run is `Running`, add the time since `dateRunnerClaimed`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  executionTime: DotNetTimeSpan;
  /**
   * When the run was last sent back to wait for a worker, in UTC: by a resume, or by answering its last question. Null if that has never happened.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateReQueuedUtc: string | null;
  /**
   * When the run started waiting for a lane, in UTC; null when it isn't waiting. A waiting run is in status New, and `GET /processes/{type}/{id}/lane` says why it waits.
   *
   * Computed by the server; ignored on input.
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  readonly waitingForLaneSinceUtc: string | null;
  /**
   * The app run that started this run from its code. Null when no app run started it. A restart keeps it.
   *
   * Format: uuid.
   */
  parentProcessId: string | null;
  /** What kind of run `parentProcessId` is. Null exactly when that is null. */
  parentProcessType: ProcessType | null;
  /**
   * For a run started by an app, the id of the run at the top of its tree, shared by every run started for the same piece of work, so you can group them without following parent links. Null when no app run started it. A restart keeps it.
   *
   * Format: uuid.
   */
  rootProcessId: string | null;
  /**
   * The automation that started this run (on a schedule, a message or by hand). Null when it was started any other way. A restart keeps it.
   *
   * Format: uuid.
   */
  triggeredByAutomatedActionId: string | null;
  /** The automation's name when it started this run. Null exactly when `triggeredByAutomatedActionId` is. */
  triggeredByAutomatedActionName: string | null;
  /** True while a retention lease keeps this run: its own, or one inherited from a retained run that started it. A retained run is never deleted when the tenant's retention period ends. Null or false: not retained. */
  retentionLeaseActive: boolean | null;
  /**
   * When the lease was taken, in UTC. For an inherited lease, when the ancestor's lease was taken.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  retentionLeaseAppliedAtUtc: string | null;
  /**
   * The id of the user who took the lease.
   *
   * Format: uuid.
   */
  retentionLeaseAppliedByUserId: string | null;
  /** The name of the user who took the lease, as it was when they took it. */
  retentionLeaseAppliedByUserName: string | null;
  /** Why it is retained, as the person who retained it wrote it (optional, at most 500 characters). */
  retentionLeaseNote: string | null;
  /**
   * Null when the lease is this run's own. Otherwise the id of the ancestor run whose lease keeps this one; releasing that run's lease releases this one too.
   *
   * Format: uuid.
   */
  retentionLeaseInheritedFromProcessId: string | null;
  /** The name of the worker machine running the run, for diagnostics. */
  hostname: string | null;
  /**
   * When the worker running the run last reported that it is alive, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRunnerPing: string | null;
  /**
   * When a worker last picked the run up, in UTC: the start of its current stretch of work. While the run is `Running`, its time so far is `executionTime` plus the time since this.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRunnerClaimed: string | null;
  /** The packages the agents installed during the run. */
  packageInstalls: CodePipelinePackageInstall[] | null;
  /**
   * The knowledge base (partition) that files the agents write to `output_files/` are uploaded to. Null: output files aren't uploaded.
   *
   * Format: uuid.
   */
  outputFilesPartitionId: string | null;
  /** The files uploaded from `output_files/` so far. */
  outputFiles: CodePipelineOutputFile[] | null;
  /** Whether the run rebases each work branch onto its source branch when they have diverged, with an agent resolving any conflicts. */
  autoRebase: boolean;
  /** The agent that resolves rebase conflicts. Null: Maitento picks one by engine. */
  rebaseAgent: string | null;
  /** For this run, the most rounds of a step's `runChallengeLoop` check, in place of the pipeline's `maxCheckLoops`. Null: the pipeline's value. Capped at 8. */
  maxCheckLoops: number | null;
  /** For this run, the most review-and-fix rounds, in place of the pipeline's `maxFixIterations`. Null: the pipeline's value. Capped at 5. */
  maxFixIterations: number | null;
  /** For this run, whether every agent gets Maitento's web tools. Null: each agent's and the pipeline's own `allowWebTools`. */
  allowWebTools: boolean | null;
  /**
   * The temporary knowledge base (partition) the run's web fetches are kept in, chosen when the run starts. Null: no agent of the run may fetch from the web.
   *
   * Format: uuid.
   */
  webDownloadPartitionId: string | null;
  /**
   * For this run, the longest every step may run, in place of each step's own `durationAutoTermination`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  stepMax: DotNetTimeSpan | null;
  /**
   * For this run, how long every step may go without activity, in place of each step's own `durationActivityTimeout`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  stepActivity: DotNetTimeSpan | null;
  /**
   * For this run, each phase's `durationAutoTermination`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  phaseMax: DotNetTimeSpan | null;
  /**
   * For this run, each phase's `durationActivityTimeout`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  phaseActivity: DotNetTimeSpan | null;
  /**
   * For this run, the pipeline's `durationAutoTermination`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  processMax: DotNetTimeSpan | null;
  /**
   * For this run, the pipeline's `durationActivityTimeout`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  processActivity: DotNetTimeSpan | null;
  /**
   * For this run, the longest one hook may run, in place of the pipeline's `hookDurationLimit`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  hook: DotNetTimeSpan | null;
  /** A reference to the run's diff, file by file. Null until the run has produced one. */
  diffRef: CodePipelineChildRef | null;
  /** A reference to the run's diff as unified diff text. Null until the run has produced one. */
  diffRawRef: CodePipelineChildRef | null;
  /** How many tool calls the run's agents have made so far. */
  toolUseCount: number | null;
  /** How many transcript entries (the agents' text and thinking) the run has so far. */
  contextEntryCount: number | null;
  /** The total size, in bytes, of the run's tool calls, transcript entries and diffs. */
  payloadBytes: number | null;
  /** The highest revision of any of the run's tool calls, transcript entries or diffs. If it hasn't changed since you last fetched them, none of them has. */
  revisionHighWater: number | null;
  /** The `resolvedCommitSha` of the run's first repository, copied here for convenience. Null for a run without repositories. */
  resolvedCommitSha: string | null;
  /** An earlier commit to diff from. A run's diff normally compares the work branch with the source branch; with this set, or a run input named `priorCommitSha`, it shows only what changed since that commit. */
  priorCommitSha: string | null;
  /**
   * The id of the user who created it. A call made with an API key is recorded as the key's user.
   *
   * Format: uuid.
   */
  userCreatedById: string;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** Steps to add to one of the pipeline's phases for a single run, so one definition can do different work each run. */
export interface CodePipelineProcessAdditionalSteps {
  /** The phase to add the steps to. It must be one of the pipeline's phases. */
  phaseName: string;
  /** The steps, added after the phase's own. */
  steps: CodePipelineStepDefinition[];
}

/**
 * Steps to add to one of the pipeline's phases for a single run, so one definition can do different work each run.
 *
 * Request shape of `CodePipelineProcessAdditionalSteps`: includes the write-only fields the server never returns.
 */
export interface CodePipelineProcessAdditionalStepsInput {
  /** The phase to add the steps to. It must be one of the pipeline's phases. */
  phaseName?: string;
  /** The steps, added after the phase's own. */
  steps?: CodePipelineStepDefinitionInput[];
}

/** For one run, a different engine or model for one of the pipeline's agents. */
export interface CodePipelineProcessAgentOverride {
  /** The agent to change: one of the pipeline's agents or the run's `additionalAgents`. */
  agentName: string;
  /** The engine to use instead of the agent's `defaultEngine`. Null: keep it. */
  engine: CodeEngineType | null;
  /** The model to use instead of the agent's `defaultModel`. Null: keep it. */
  model: string | null;
}

/**
 * For one run, a different engine or model for one of the pipeline's agents.
 *
 * Request shape of `CodePipelineProcessAgentOverride`: includes the write-only fields the server never returns.
 */
export interface CodePipelineProcessAgentOverrideInput {
  /** The agent to change: one of the pipeline's agents or the run's `additionalAgents`. */
  agentName?: string;
  /** The engine to use instead of the agent's `defaultEngine`. Null: keep it. */
  engine?: CodeEngineType | null;
  /** The model to use instead of the agent's `defaultModel`. Null: keep it. */
  model?: string | null;
}

/** An answer to a question an agent asked during a code pipeline run. Once every question is answered, the run carries on. */
export interface CodePipelineProcessAnswerRequest {
  /**
   * The question's `id`, from the step's `humanInteractionRequests`.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   * Format: uuid.
   */
  requestId: string;
  /**
   * The answer: one of the suggested answers, or your own.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  answer: string;
}

/** One entry of an agent's transcript in a code pipeline run: something it wrote, or its thinking. Together with the run's tool calls, in `sequence` order, it gives the agent's whole transcript. */
export interface CodePipelineProcessContextEntry {
  /**
   * The `id` of the step (in the run's `phases`) the entry belongs to.
   *
   * Format: uuid.
   */
  stepExecutionId: string;
  /** The name of the phase the entry belongs to. */
  phaseName: string;
  /** The name of the agent that wrote the entry. */
  agentName: string;
  /** The name of the step the entry belongs to. */
  stepName: string;
  /** The entry's position in the step's transcript. Tool calls and transcript entries share one numbering, so sorting both by it gives the order things happened in. */
  sequence: number;
  /**
   * When the agent wrote it, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  timestamp: string;
  /** Whether the entry is text the agent wrote or its thinking. */
  kind: CodePipelineProcessContextEntryKind;
  /** The entry's text. */
  body: string;
  /** The size of the text as the agent wrote it, in UTF-8 bytes, before any shortening. */
  originalBytes: number;
  /** Whether `body` was shortened because it was very large. */
  isTruncated: boolean;
  /**
   * The id of the code pipeline run it belongs to.
   *
   * Format: uuid.
   */
  codePipelineProcessId: string;
  /** Its revision, which goes up each time it changes (a tool result arriving after its call, for example). Starts at 1. Compare it with the `rev` in the run's references to tell whether your copy is current. */
  rev: number;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/**
 * A credential a code pipeline run's engines use: an API key (`"apiKey"`) or a coding tool's sign-in (`"oauth"`). Every agent on the same engine shares the engine's credentials, which are tried in order: the next one is used when a credential is rejected, rate-limited or out of quota.
 *
 * Discriminated by `type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type CodePipelineProcessCredentials =
  | CodePipelineApiKeyCredentials
  | CodePipelineOAuthCredentials;

/**
 * A credential a code pipeline run's engines use: an API key (`"apiKey"`) or a coding tool's sign-in (`"oauth"`). Every agent on the same engine shares the engine's credentials, which are tried in order: the next one is used when a credential is rejected, rate-limited or out of quota.
 *
 * Request shape of `CodePipelineProcessCredentials`: includes the write-only fields the server never returns.
 * Discriminated by `type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type CodePipelineProcessCredentialsInput =
  | CodePipelineApiKeyCredentialsInput
  | CodePipelineOAuthCredentialsInput;

/** A code pipeline run's changes, file by file and line by line. */
export interface CodePipelineProcessDiff {
  /** The changes. */
  diff: CodeDiff;
  /** How many files changed. */
  fileCount: number;
  /** Whether the diff was too large to keep whole, so the line-by-line changes were left out and only the changed files are listed. Says nothing about whether the raw diff was cut too. */
  isTruncated: boolean;
  /**
   * The id of the code pipeline run it belongs to.
   *
   * Format: uuid.
   */
  codePipelineProcessId: string;
  /** Its revision, which goes up each time it changes (a tool result arriving after its call, for example). Starts at 1. Compare it with the `rev` in the run's references to tell whether your copy is current. */
  rev: number;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** A code pipeline run's changes as unified diff text, as git produces it. */
export interface CodePipelineProcessDiffRaw {
  /** The unified diff text. */
  diffRaw: string;
  /** The size of the diff as git produced it, in UTF-8 bytes, before any shortening. */
  originalBytes: number;
  /** Whether the text was cut short because it was too large. Says nothing about whether the file-by-file diff was cut too. */
  isTruncated: boolean;
  /**
   * The id of the code pipeline run it belongs to.
   *
   * Format: uuid.
   */
  codePipelineProcessId: string;
  /** Its revision, which goes up each time it changes (a tool result arriving after its call, for example). Starts at 1. Compare it with the `rev` in the run's references to tell whether your copy is current. */
  rev: number;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** An MCP server that runs from a repository's checkout over standard input and output, so a run's agents can call the repository's own tools. Coding tools that support such servers start it in the checkout folder. */
export interface CodePipelineProcessMcpServer {
  /** The program that starts the server, for example `node`, `python` or `npx`. */
  command: string;
  /** The arguments to pass to `command`, for example `["dist/server.js"]`. May be empty. */
  args: string[];
}

/**
 * An MCP server that runs from a repository's checkout over standard input and output, so a run's agents can call the repository's own tools. Coding tools that support such servers start it in the checkout folder.
 *
 * Request shape of `CodePipelineProcessMcpServer`: includes the write-only fields the server never returns.
 */
export interface CodePipelineProcessMcpServerInput {
  /** The program that starts the server, for example `node`, `python` or `npx`. */
  command?: string;
  /** The arguments to pass to `command`, for example `["dist/server.js"]`. May be empty. */
  args?: string[];
}

/** The tool calls and transcript entries of a run to fetch, by id: typically the ones the run's references list that you don't have, or have at an older revision. It only reads, so you can repeat it safely. */
export interface CodePipelineProcessPayloadsByIdsRequest {
  /**
   * The ids of the tool calls to fetch. At most 500; ask for more in further requests. Send an empty array for none.
   *
   * Format: each uuid.
   */
  toolUseIds?: string[];
  /**
   * The ids of the transcript entries to fetch. At most 500; ask for more in further requests. Send an empty array for none.
   *
   * Format: each uuid.
   */
  contextEntryIds?: string[];
}

/** Tool calls and transcript entries of a code pipeline run. To read a step's transcript in order, merge its entries from the two lists by `sequence`. Fetched for one step, each list is in `sequence` order; fetched by id, they may span steps and are not sorted. */
export interface CodePipelineProcessPayloadsResponse {
  /** The tool calls. Never null. */
  toolUses: CodePipelineProcessToolUse[];
  /** The transcript entries (the agents' text and thinking). Never null. */
  contextEntries: CodePipelineProcessContextEntry[];
}

/**
 * A git repository for a code pipeline run, over SSH (`"ssh"`) or HTTPS (`"http"`). With one repository it is checked out to `/code`; with several, each goes to `/code/<name>`.
 *
 * Discriminated by `type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type CodePipelineProcessRepo =
  | CodePipelineGitHttpRepo
  | CodePipelineGitSshRepo;

/**
 * A git repository for a code pipeline run, over SSH (`"ssh"`) or HTTPS (`"http"`). With one repository it is checked out to `/code`; with several, each goes to `/code/<name>`.
 *
 * Request shape of `CodePipelineProcessRepo`: includes the write-only fields the server never returns.
 * Discriminated by `type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type CodePipelineProcessRepoInput =
  | CodePipelineGitHttpRepoInput
  | CodePipelineGitSshRepoInput;

/** Resumes a code pipeline run that failed, was killed or has had its questions answered, with a prompt for the agent. The step that failed or was interrupted carries on in the agent's same session with this prompt, instead of starting over with its own. */
export interface CodePipelineProcessResumeWithPromptRequest {
  /**
   * What to tell the agent, for example what went wrong and how to carry on.
   *
   * Sent as-is: the server does not trim it.
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  continuationPrompt: string;
  /** New credentials for the run's engines, to replace the ones it started with, for example when a token has expired. Null or empty: keep the run's credentials. */
  credentials?: CodePipelineProcessCredentialsInput[] | null;
  /** A credential stack (name or id) to run on from here, snapshotted now, in place of the credentials or stack the run started with. Not with `credentials`. Null: keep the run's stack. Sending `credentials` instead moves the run off its stack and onto them. */
  credentialStack?: string | null;
  /** New repositories, with fresh git credentials, to replace the ones the run started with, for example when a short-lived token has expired. Null or empty: keep the run's repositories. */
  repos?: CodePipelineProcessRepoInput[] | null;
}

/** An automation action (`$type` is `codepipeline`) that starts a code pipeline run. The code pipeline is named by `name` and `namespaceName`, not by `version`; `request` is the start request to send. */
export interface CodePipelineProcessStartConfig {
  /** Discriminator: always `"codepipeline"` for this type; send it as the first property. */
  $type: "codepipeline";
  /** The name of the code pipeline to start. */
  name: string;
  /** The name of the namespace the code pipeline is in. */
  namespaceName: string;
  /** The start request to send, exactly as for starting the code pipeline directly: inputs, repositories, extra steps, agent overrides, credentials, mounts, input files and so on. */
  request: CodePipelineProcessStartRequest;
  /** The app, interaction or capsule to start, and the version of it. Required for those three; left out for `codepipeline` (named by `name`) and `interaction-message` (which names a run). */
  version: VersionReference | null;
}

/**
 * An automation action (`$type` is `codepipeline`) that starts a code pipeline run. The code pipeline is named by `name` and `namespaceName`, not by `version`; `request` is the start request to send.
 *
 * Request shape of `CodePipelineProcessStartConfig`: includes the write-only fields the server never returns.
 */
export interface CodePipelineProcessStartConfigInput {
  /** Discriminator: always `"codepipeline"` for this type; send it as the first property. */
  $type: "codepipeline";
  /** The name of the code pipeline to start. */
  name?: string;
  /** The name of the namespace the code pipeline is in. */
  namespaceName?: string;
  /** The start request to send, exactly as for starting the code pipeline directly: inputs, repositories, extra steps, agent overrides, credentials, mounts, input files and so on. */
  request?: CodePipelineProcessStartRequestInput;
  /** The app, interaction or capsule to start, and the version of it. Required for those three; left out for `codepipeline` (named by `name`) and `interaction-message` (which names a run). */
  version?: VersionReference | null;
}

/** Starts a run of a code pipeline: its inputs, the repositories to work on, and any changes to the pipeline for this run. */
export interface CodePipelineProcessStartRequest {
  /**
   * Your own id for this start, to make retries safe: starting again with the same id returns the run it already created instead of starting a second one. Null: every start creates a new run.
   *
   * Format: uuid.
   */
  launchIntentId: string | null;
  /** The run's input values, by input name. Send an empty array when there are none. */
  inputs: NameValuePair[];
  /** Different engines or models for some of the agents, for this run. */
  agentOverrides: CodePipelineProcessAgentOverride[] | null;
  /** Agents for this run only, alongside the pipeline's own. Steps, overrides and the review panel can name them. Each needs a `role` and a name of lower-case letters, digits and hyphens (up to 63 characters, not starting with a hyphen) that no other agent has. At most 16. */
  additionalAgents: CodePipelineAgent[] | null;
  /** The run's review panel. Each reviewer's step must be in the panel's phase (from the pipeline, or added with `additionalSteps`) with the same agent and output variable, and each reviewer's output variable must be unique. */
  reviewPanel: CodePipelineReviewPanel | null;
  /** For this run, how many of a phase's steps may run at once, in place of the pipeline's `maxParallelSteps`. Null: the pipeline's value. Between 1 and 16. */
  maxParallelSteps: number | null;
  /** Steps to add to the pipeline's phases for this run only. */
  additionalSteps: CodePipelineProcessAdditionalSteps[] | null;
  /** Credentials for the engines, tried before your tenant's model keys. Optional: without them, the engines use your tenant's model keys, then (unless your tenant forbids it) Maitento's own. Your own API keys must not be empty. */
  credentials: CodePipelineProcessCredentials[];
  /** The credential stack the run's engines use, by id or name: its API keys and coding-agent sign-ins, in the stack's order, and never Maitento's own keys. An engine the stack can't serve stops the run before it starts. Leave it out to use the pipeline's own stack, then the namespace's default, then your tenant's. Can't be combined with `credentials`. */
  credentialStack: string | null;
  /** The git repositories to work on, with credentials that can push. Send an empty array to run without one. */
  repos: CodePipelineProcessRepo[];
  /** File systems to mount for the run's agents. */
  vfsMounts: CodePipelineProcessVfsMount[] | null;
  /** An extra system prompt for this run, applied on top of the pipeline's and agents' prompts. */
  systemPromptOverride: string | null;
  /**
   * Uploaded files to copy into the agents' `files/` folder before the run starts. They must belong to your tenant.
   *
   * Format: each uuid.
   */
  inputFileIds: string[] | null;
  /**
   * A knowledge base (partition) to upload the files the agents write to `output_files/` to, as the run goes. It must belong to your tenant. Null: output files aren't uploaded.
   *
   * Format: uuid.
   */
  outputFilesPartitionId: string | null;
  /** Whether to rebase each work branch onto its source branch when they have diverged, with an agent resolving any conflicts. Default `true`. Skipped for a repository whose work branch is its source branch. */
  autoRebase: boolean;
  /** The agent that resolves rebase conflicts. Null: the first available of the run's agents by engine, in this order: Claude, Glm, Codex, Gemini, Qwen, DeepSeek, Kimi. */
  rebaseAgent: string | null;
  /** For this run, the most rounds of a step's `runChallengeLoop` check, in place of the pipeline's `maxCheckLoops`. Null: the pipeline's value. Capped at 8. */
  maxCheckLoops: number | null;
  /** For this run, the most review-and-fix rounds, in place of the pipeline's `maxFixIterations`. Null: the pipeline's value. Capped at 5. */
  maxFixIterations: number | null;
  /** For this run, whether every agent gets Maitento's web tools. Null: each agent's and the pipeline's own `allowWebTools`. */
  allowWebTools: boolean | null;
  /**
   * The temporary knowledge base (partition) the run's web fetches are kept in. Null: the pipeline's namespace default, then your tenant's. A run whose agents may use the web tools is refused when none of the three is set.
   *
   * Format: uuid.
   */
  webDownloadPartitionId: string | null;
  /**
   * For this run, the longest every step may run, in place of each step's own `durationAutoTermination`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  stepMax: DotNetTimeSpan | null;
  /**
   * For this run, how long every step may go without activity, in place of each step's own `durationActivityTimeout`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  stepActivity: DotNetTimeSpan | null;
  /**
   * For this run, each phase's `durationAutoTermination`: the limit for steps that set none of their own.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  phaseMax: DotNetTimeSpan | null;
  /**
   * For this run, each phase's `durationActivityTimeout`: the limit for steps that set none of their own.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  phaseActivity: DotNetTimeSpan | null;
  /**
   * For this run, the pipeline's `durationAutoTermination`: the limit for steps whose step and phase set none.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  processMax: DotNetTimeSpan | null;
  /**
   * For this run, the pipeline's `durationActivityTimeout`: the limit for steps whose step and phase set none.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  processActivity: DotNetTimeSpan | null;
  /**
   * For this run, the longest one hook may run, in place of the pipeline's `hookDurationLimit`.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  hook: DotNetTimeSpan | null;
}

