/** How one step of a code pipeline run is going: its status, output, token usage, questions and the agent's transcript. */
export interface CodePipelineStepExecution {
  /**
   * The step's id within the run. Tool calls and transcript entries refer to it as `stepExecutionId`, and you use it to fetch them.
   *
   * Format: uuid.
   */
  id: string;
  /** The step's name. */
  stepName: string;
  /** The agent running the step. */
  agentName: string;
  /** Where the step is. */
  status: CodePipelineStepExecutionStatus;
  /** What the agent has written so far, taken from the coding tool's output. */
  output: string | null;
  /** The step's result. For a step with `outputJsonSchema`, the JSON that matches the schema. */
  finalResult: string | null;
  /** The agent's structured summary of the step, for a step with `isStructuredOutput`. */
  outputStructured: CodePipelineStructuredOutput | null;
  /** Why the step failed. Null unless it did. */
  failureDetails: string | null;
  /**
   * When the step started, in UTC. Null until it starts.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateStart: string | null;
  /**
   * When the step ended, in UTC. Null until it ends.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateEnd: string | null;
  /** Whether the step made a git commit. */
  didCommit: boolean;
  /** The tokens the step used, by token type and model. */
  tokenUsage: CodePipelineTokenUsageEntry[] | null;
  /** The questions the agent asked a person during the step, with their answers. */
  humanInteractionRequests: CodePipelineHumanInteractionRequest[] | null;
  /** The coding tool's session id when the step last ran, so a resumed step continues the same conversation. Null for coding tools without resumable sessions. */
  engineSessionId: string | null;
  /** Every call the step made to its coding tool, with the exit code and output streams, whether it succeeded or failed, across retries and resumes. The list is capped, keeping the first and latest calls. */
  outputs: CodePipelineEngineOutput[] | null;
  /** The rounds of the step's "is it really done?" check, for a step with `runChallengeLoop`. Null or empty for other steps. */
  challengeLoopTurns: CodePipelineChallengeTurn[] | null;
  /** References to the step's tool calls, which you fetch separately. An empty array means the step made no tool calls. */
  toolUseRefs: CodePipelineChildRef[] | null;
  /** References to the step's transcript entries (the agent's text and thinking), which you fetch separately. An empty array means there are none. */
  contextEntryRefs: CodePipelineChildRef[] | null;
}

/** The agent's own summary of a step, asked for after the step (`isStructuredOutput`). */
export interface CodePipelineStructuredOutput {
  /** A line or two on what the step achieved. */
  summary: string | null;
  /** Whether the agent says the step did what it was asked. */
  wasSuccessful: boolean;
  /** Whether the agent is stuck on something it can't resolve by itself. */
  isBlocked: boolean;
  /** What the agent is stuck on, when `isBlocked` is true. */
  blockedReason: string | null;
  /** Whether the agent says more work is needed beyond this step. */
  isAdditionalWorkRequired: boolean;
}

/** A count of one type of token a step used, with the model and credential that used them. */
export interface CodePipelineTokenUsageEntry {
  /** The token type, as the provider reports it, for example `input`, `output`, `cache_read`, `cache_creation_5m` or `cache_creation_1h`. */
  type: string;
  /** How many tokens of this type. */
  amount: number;
  /** The model the tokens are counted against: `wireModel` when the coding tool reported one, otherwise `resolvedModel`. Null when unknown. */
  model: string | null;
  /** The model the coding tool reported it actually ran on. Null when the coding tool doesn't report one. */
  wireModel: string | null;
  /** The model the run's `agentOverrides` asked for, for this step's agent. Null when no override named one. */
  requestedModel: string | null;
  /** The model chosen for this step's agent: the override's model, else the agent's `defaultModel`. */
  resolvedModel: string | null;
  /** The `credentialId` of the credential that used these tokens. Null when unknown. */
  credentialId: string | null;
  /** The model's pricing tier these tokens fell in, for models priced by request size (for example `large-context`). Null: the model's standard rate. */
  tier: string | null;
}

/** A new definition for an existing code pipeline. It is added as a new version; earlier versions are kept. */
export interface CodePipelineUpdateRequest {
  /**
   * The pipeline's name, unique within its namespace. At most 128 characters.
   *
   * Validation: maxLength: 128; required (empty or whitespace-only strings are rejected).
   */
  name: string;
  /**
   * The pipeline's agents. At least one.
   *
   * Validation: minLength: 1; required (empty or whitespace-only strings are rejected).
   */
  agents: CodePipelineAgentInput[];
  /**
   * The pipeline's phases, each a group of steps. At least one.
   *
   * Validation: minLength: 1; required (empty or whitespace-only strings are rejected).
   */
  phases: CodePipelinePhaseDefinitionInput[];
  /** MCP tools every agent of the pipeline may use. */
  externalOperationsMcp?: McpExternalOperationBindingInput[];
  /** OpenAPI tools every agent of the pipeline may use. */
  externalOperationsOpenApi?: OpenApiExternalOperationBindingInput[];
  /** Inputs a run supplies as secrets for the tools' authentication. */
  authenticationSecretInputs?: ConnectorAuthenticationSecretInputInput[];
  /** Inputs a run supplies as values bound into the tools' calls. */
  bindingInputs?: ConnectorBindingInputInput[];
  /** Inputs a run supplies for the step prompts (`%%input:name%%`). */
  promptInputs?: PromptInputInput[];
  /** File systems the pipeline declares for its agents. A run mounts only the file systems in its own `vfsMounts`. */
  vfsBindings?: CodePipelineVfsBindingInput[];
  /**
   * The app that holds the pipeline's hooks (its Cogniscript methods). Null: no hooks.
   *
   * Format: uuid.
   */
  cogniscriptAppId?: string | null;
  /**
   * System prompts every agent of the pipeline gets.
   *
   * Sent as-is: the server does not trim it.
   */
  systemPrompts?: string[] | null;
  /** How the pipeline's `systemPrompts` combine with the ones before them. Null: `Additional`. */
  systemPromptMode?: CodePipelineSystemPromptMode | null;
  /** The namespace of a file system to save the agents' sessions in, so a resumed or restarted run carries on from them. Null: sessions are not saved. */
  resumeVfsNamespace?: string | null;
  /** The name of that file system, within `resumeVfsNamespace`. Null: `default`. */
  resumeVfsName?: string | null;
  /**
   * Not used by code pipeline runs.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarning?: DotNetTimeSpan | null;
  /**
   * The longest any step may run, for steps whose step and phase set no `durationAutoTermination`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination?: DotNetTimeSpan | null;
  /**
   * How long any step may go without activity before it is stopped, for steps whose step and phase set no `durationActivityTimeout`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationActivityTimeout?: DotNetTimeSpan | null;
  /**
   * The longest one hook may run. Null: 30 seconds.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  hookDurationLimit?: DotNetTimeSpan | null;
  /** Not used by code pipeline runs. */
  includeEnvironmentInfo?: boolean;
  /** Whether the agents may stop and ask a person a question. The run then waits in `HumanInteractionRequired` until it is answered. */
  allowHumanInteraction?: boolean;
  /** Whether the pipeline's agents get Maitento's web search and fetch tools. Off by default. */
  allowWebTools?: boolean;
  /** The name of a hook to run when the run hits an infrastructure error, such as a failed clone or push. */
  onErrorHook?: string | null;
  /** The most review-and-fix rounds a hook's fix loop may run. Null: 3. Capped at 5. */
  maxFixIterations?: number | null;
  /** For a fix loop that ends on the agents' own confidence: the confidence, from 0 to 1, at which it stops. Null: 0.8. */
  confidenceThreshold?: number | null;
  /** The most phases hooks may add to one run in total. Null: 24. */
  maxInjectedPhases?: number | null;
  /** How many of a phase's steps may run at once. Null: 6. Between 1 and 16. */
  maxParallelSteps?: number | null;
  /** The credential stack the pipeline's runs use, by id or name, when their start doesn't name one: its API keys and coding-agent sign-ins serve the engines, and Maitento's own keys never do. Null: the namespace's default stack, then your tenant's. */
  credentialStack?: string | null;
}

/** One version of a code pipeline's definition: its agents, phases, inputs, tools and limits. */
export interface CodePipelineVersion {
  /** The pipeline's agents. */
  agents: CodePipelineAgent[];
  /** The pipeline's phases, each a group of steps. */
  phases: CodePipelinePhaseDefinition[];
  /** MCP tools every agent of the pipeline may use. */
  externalOperationsMcp: McpExternalOperationBinding[];
  /** OpenAPI tools every agent of the pipeline may use. */
  externalOperationsOpenApi: OpenApiExternalOperationBinding[];
  /** Inputs a run supplies as secrets for the tools' authentication. */
  authenticationSecretInputs: ConnectorAuthenticationSecretInput[];
  /** Inputs a run supplies as values bound into the tools' calls. */
  bindingInputs: ConnectorBindingInput[];
  /** Inputs a run supplies for the step prompts (`%%input:name%%`). */
  promptInputs: PromptInput[];
  /** File systems the pipeline declares for its agents. A run mounts only the file systems in its own `vfsMounts`. */
  vfsBindings: CodePipelineVfsBinding[];
  /**
   * The app that holds the pipeline's hooks (its Cogniscript methods), built from `code-pipeline-hooks/<pipeline>/` when you deploy. Null: the pipeline has no hooks.
   *
   * Format: uuid.
   */
  cogniscriptAppId: string | null;
  /** System prompts every agent of the pipeline gets. */
  systemPrompts: string[] | null;
  /** How the pipeline's `systemPrompts` combine with the ones before them. Null: `Additional`. An agent whose own mode is `Override` uses only its own prompts. */
  systemPromptMode: CodePipelineSystemPromptMode | null;
  /** The namespace of a file system to save the agents' sessions in when a run finishes, fails or waits for an answer, so a resumed or restarted run carries on from them. Null: sessions are not saved. */
  resumeVfsNamespace: string | null;
  /** The name of that file system, within `resumeVfsNamespace`. Null: `default`. */
  resumeVfsName: string | null;
  /**
   * Not used by code pipeline runs.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarning: DotNetTimeSpan | null;
  /**
   * The longest any step may run, for steps whose step and phase set no `durationAutoTermination`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination: DotNetTimeSpan | null;
  /**
   * How long any step may go without activity before it is stopped, for steps whose step and phase set no `durationActivityTimeout`. Null: Maitento's default.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationActivityTimeout: DotNetTimeSpan | null;
  /**
   * The longest one hook may run. Null: 30 seconds.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  hookDurationLimit: DotNetTimeSpan | null;
  /** The most review-and-fix rounds a hook's fix loop may run. Null: 3. Capped at 5. */
  maxFixIterations: number | null;
  /** For a fix loop that ends on the agents' own confidence: the confidence, from 0 to 1, at which it stops. Null: 0.8. */
  confidenceThreshold: number | null;
  /** The most phases hooks may add to one run in total. Null: 24. */
  maxInjectedPhases: number | null;
  /** The most rounds of a step's `runChallengeLoop` check. Null: 5. Capped at 8. */
  maxCheckLoops: number | null;
  /** How many of a phase's steps may run at once. Null: 6. Between 1 and 16. Steps still wait for the steps they depend on. */
  maxParallelSteps: number | null;
  /** The credential stack the pipeline's runs use, by id or name, when their start doesn't name one: its API keys and coding-agent sign-ins serve the engines, and Maitento's own keys never do. Null: the namespace's default stack, then your tenant's. */
  credentialStack: string | null;
  /** In a review-and-fix loop, the most critical findings the reviewers may report before another fix round runs. Null: 0. */
  reviewGateCriticalMax: number | null;
  /** In a review-and-fix loop, the most high-severity findings the reviewers may report before another fix round runs. Null: 2. */
  reviewGateHighMax: number | null;
  /** In a review-and-fix loop, the most medium-severity findings the reviewers may report before another fix round runs. Null: 10. */
  reviewGateMediumMax: number | null;
  /** Not used by code pipeline runs. */
  includeEnvironmentInfo: boolean;
  /** Whether the agents may stop and ask a person a question. The run then waits in `HumanInteractionRequired` until it is answered. When false, the run never asks. */
  allowHumanInteraction: boolean;
  /** Whether the pipeline's agents get Maitento's web search and fetch tools. Off by default. An agent's `allowWebTools`, and a run's, override it. The coding tools' own web access is always off. */
  allowWebTools: boolean;
  /** The name of a hook to run when the run hits an infrastructure error, such as a failed clone or push. It receives the event type, the error and the attempt number, and returns JSON with a `decision`: `"retry"`, `"skip"`, or `"fail"` with a `reason`. */
  onErrorHook: string | null;
  /** The version number, from 1. Every change to a definition adds a new version with the next number. */
  version: number;
  /**
   * When this version was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  date: string;
  /** Whether this version is disabled. A disabled version is never used: new links and runs take the latest enabled version, and anything pinned to this one fails until it is re-enabled. */
  isDisabled: boolean;
}

/** A file system (VFS) a code pipeline declares for its agents. It is stored with the pipeline, but a run mounts only the file systems in its own `vfsMounts`. */
export interface CodePipelineVfsBinding {
  /** The name the file system is known by. */
  name: string;
  /**
   * The file system's id, or null when none is named.
   *
   * Format: uuid.
   */
  vfsId: string | null;
  /** Whether the agents may change the file system or only read it. */
  mode: CodePipelineVfsMode;
  /** A description of what the file system holds. */
  context: string | null;
}

/**
 * A file system (VFS) a code pipeline declares for its agents. It is stored with the pipeline, but a run mounts only the file systems in its own `vfsMounts`.
 *
 * Request shape of `CodePipelineVfsBinding`: includes the write-only fields the server never returns.
 */
export interface CodePipelineVfsBindingInput {
  /** The name the file system is known by. */
  name?: string;
  /**
   * The file system's id, or null when none is named.
   *
   * Format: uuid.
   */
  vfsId?: string | null;
  /** Whether the agents may change the file system or only read it. */
  mode?: CodePipelineVfsMode;
  /** A description of what the file system holds. */
  context?: string | null;
}

/** A source file sent to a build: its name and its lines. */
export interface CompilationInputFile {
  /**
   * The file's path in the project. Build messages about the file name it.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  filename: string;
  /**
   * The file's text, one entry per line, kept exactly as sent (whitespace included).
   *
   * Sent as-is: the server does not trim it.
   * Validation: minLength: 1; required (empty or whitespace-only strings are rejected).
   */
  lines: string[];
}

/** One message from a build, with where in the project it came from when it is about a file. */
export interface CompilationLogEntry {
  /** The message, in English. */
  text: string;
  /**
   * When the message was written, in UTC.
   *
   * Computed by the server; ignored on input.
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  readonly date: string;
  /** How serious the message is. Any `Error` fails the build. */
  logLevel: CompilationLogLevel;
  /** The file the message is about; null when it is about the build as a whole. */
  filename: string | null;
  /** The line in the file the message is about, when known. */
  lineNumber: number | null;
  /** The character in the line the message is about, when known. */
  character: number | null;
}

/**
 * A connector: one endpoint, described once (its URL, request and response, and the kind of credential it needs). Agents never call a connector directly: a tool points at it. Each change adds a new version, and a tool keeps calling the exact version it was built against.
 *
 * Discriminated by `$type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type Connector =
  | McpConnector
  | OpenApiConnector;

/** A credential sent with every call of a tool: a secret's value, in an HTTP header. The tool's connector needs `Header` authentication. */
export interface ConnectorAuthenticationHeader {
  /** The HTTP header the secret's value is sent in. For `Authorization`, a value without a space is sent as `Bearer <value>`. */
  headerName: string;
  /**
   * The id of the secret whose value is sent.
   *
   * Format: uuid.
   */
  secretId: string;
}

/** A run input that chooses the secret a tool sends with its calls: a run gives the id of a secret, such as one per customer, and the tool sends its value in an HTTP header. */
export interface ConnectorAuthenticationSecretInput {
  /**
   * The id of the tool whose calls send the secret.
   *
   * Format: uuid.
   */
  externalOperationId: string;
  /**
   * Only the participant filled by this agent sends the secret. Null: every participant does.
   *
   * Format: uuid.
   */
  agentId: string | null;
  /**
   * The id of the secret sent when a run does not choose one. Null: none.
   *
   * Format: uuid.
   */
  defaultSecretId: string | null;
  /** The HTTP header the secret's value is sent in, such as `Authorization`. */
  headerName: string;
  /** The input's name: a run gives the input's value under this name. */
  name: string;
  /** What the input is for, shown to whoever starts a run. */
  description: string | null;
  /** Whether a run must give the input. A run started without a required input is refused. */
  isRequired: boolean;
}

/**
 * A run input that chooses the secret a tool sends with its calls: a run gives the id of a secret, such as one per customer, and the tool sends its value in an HTTP header.
 *
 * Request shape of `ConnectorAuthenticationSecretInput`: includes the write-only fields the server never returns.
 */
export interface ConnectorAuthenticationSecretInputInput {
  /**
   * The id of the tool whose calls send the secret.
   *
   * Format: uuid.
   */
  externalOperationId?: string;
  /**
   * Only the participant filled by this agent sends the secret. Null: every participant does.
   *
   * Format: uuid.
   */
  agentId?: string | null;
  /**
   * The id of the secret sent when a run does not choose one. Null: none.
   *
   * Format: uuid.
   */
  defaultSecretId?: string | null;
  /** The HTTP header the secret's value is sent in, such as `Authorization`. */
  headerName?: string;
  /**
   * The input's name: a run gives the input's value under this name.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  name: string;
  /**
   * What the input is for, shown to whoever starts a run.
   *
   * Validation: minLength: 1.
   */
  description?: string | null;
  /** Whether a run must give the input. A run started without a required input is refused. */
  isRequired?: boolean;
}

/** A fixed value for one field or parameter of a tool's calls. The model never sees or chooses a bound value. */
export interface ConnectorBinding {
  /** What the value fills: a request body field (separate the names of a nested field with `/`), or a path or query parameter, depending on which list the binding is in. */
  target: string;
  /** The value, as text. */
  value: string;
}

/** A run input whose value is written straight into a tool's calls, such as a customer id, so the model never sees or chooses it. */
export interface ConnectorBindingInput {
  /**
   * The id of the tool whose calls get the value.
   *
   * Format: uuid.
   */
  externalOperationId: string;
  /**
   * Only the participant filled by this agent gets the value. Null: every participant does.
   *
   * Format: uuid.
   */
  agentId: string | null;
  /** Where the value goes: the name of the request body field (a nested field's names separated by `/`), or of the path or query parameter, as `type` says. */
  target: string;
  /** The value used when a run does not give one. Null: none. */
  defaultValue: string | null;
  /** What `target` names: a request body field, a query parameter or a path parameter. */
  type: ConnectorBindingInputType;
  /** The input's name: a run gives the input's value under this name. */
  name: string;
  /** What the input is for, shown to whoever starts a run. */
  description: string | null;
  /** Whether a run must give the input. A run started without a required input is refused. */
  isRequired: boolean;
}

/**
 * A run input whose value is written straight into a tool's calls, such as a customer id, so the model never sees or chooses it.
 *
 * Request shape of `ConnectorBindingInput`: includes the write-only fields the server never returns.
 */
export interface ConnectorBindingInputInput {
  /**
   * The id of the tool whose calls get the value.
   *
   * Format: uuid.
   */
  externalOperationId?: string;
  /**
   * Only the participant filled by this agent gets the value. Null: every participant does.
   *
   * Format: uuid.
   */
  agentId?: string | null;
  /** Where the value goes: the name of the request body field (a nested field's names separated by `/`), or of the path or query parameter, as `type` says. */
  target?: string;
  /** The value used when a run does not give one. Null: none. */
  defaultValue?: string | null;
  /** What `target` names: a request body field, a query parameter or a path parameter. */
  type?: ConnectorBindingInputType;
  /**
   * The input's name: a run gives the input's value under this name.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  name: string;
  /**
   * What the input is for, shown to whoever starts a run.
   *
   * Validation: minLength: 1.
   */
  description?: string | null;
  /** Whether a run must give the input. A run started without a required input is refused. */
  isRequired?: boolean;
}

/** Creates an automation in a namespace: what it starts. Add its schedules and message triggers afterwards. */
export interface CreateAutomatedActionRequest {
  /** The automation's name, unique within the namespace. */
  name?: string;
  /** What the automation is for. */
  description?: string | null;
  /** What the automation starts each time it fires, at least one: one run per action. */
  actions?: AutomatedActionItemInput[];
}

/** Where an Anthropic credential reaches Claude when it isn't Anthropic's own API: Amazon Bedrock in a region, or Google Vertex AI in a project and region. Only code pipelines' Claude Code agents can run on such a credential. */
export interface CredentialCloud {
  kind: CredentialCloudKind;
  /** The AWS region, such as `us-east-1`. Required for Bedrock. */
  awsRegion: string | null;
  /** The Google Cloud project id. Required for Vertex. */
  gcpProjectId: string | null;
  /** The Vertex region, such as `us-east5` or `global`. Required for Vertex. */
  gcpRegion: string | null;
}

/**
 * Where an Anthropic credential reaches Claude when it isn't Anthropic's own API: Amazon Bedrock in a region, or Google Vertex AI in a project and region. Only code pipelines' Claude Code agents can run on such a credential.
 *
 * Request shape of `CredentialCloud`: includes the write-only fields the server never returns.
 */
export interface CredentialCloudInput {
  kind?: CredentialCloudKind;
  /** The AWS region, such as `us-east-1`. Required for Bedrock. */
  awsRegion?: string | null;
  /** The Google Cloud project id. Required for Vertex. */
  gcpProjectId?: string | null;
  /** The Vertex region, such as `us-east5` or `global`. Required for Vertex. */
  gcpRegion?: string | null;
}

/** How a credential has been behaving. A credential that keeps failing is switched off for a while (a circuit breaker), so a broken endpoint isn't called on every run, and after repeated breaks until it's tested again. */
export interface CredentialHealth {
  /** Failures that count against the credential since it last served a call. */
  consecutiveFailures: number;
  /**
   * While set and in the future, runs skip the credential.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  disabledUntilUtc: string | null;
  /** How many times the breaker has opened since the last success. */
  breaks: number;
  /** Switched off after repeated breaks: runs skip the credential until a test of it passes (or its keys or endpoint are changed). Null on a credential saved before this existed, read as false. */
  offUntilTested: boolean | null;
  /**
   * When the last failure that counted against the credential happened.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  lastFailureAtUtc: string | null;
  /** Why it failed: `Auth`, `Quota`, `Endpoint` or `Unreachable`. */
  lastFailureReason: string | null;
  /** Format: ISO-8601 date-time, up to 7 fractional digits. */
  lastTestedAtUtc: string | null;
  lastTestSucceeded: boolean | null;
  /** A stable code for why the last test failed. */
  lastTestError: string | null;
}

/** How one of a credential's keys did in a test. Never the endpoint's response itself: only its status. */
export interface CredentialKeyTestResult {
  /** Format: uuid. */
  keyId: string;
  keyHint: string;
  succeeded: boolean;
  /** Why it failed (`CredentialErrorCodes`); null when it passed. */
  errorCode: string | null;
  /** The HTTP status the endpoint answered with; null when no answer came. */
  statusCode: number | null;
}

/** A model a credential may serve. */
export interface CredentialModel {
  /** The model, as runs name it (for example `gpt-5` or `claude-sonnet-4-5`). */
  model: string;
  /** The name the endpoint knows it by, where that differs (an Azure or Foundry deployment). */
  deploymentName: string | null;
  /** The context window the endpoint gives it, where that's smaller than the model's own. */
  contextWindowTokens: number | null;
}

/**
 * A model a credential may serve.
 *
 * Request shape of `CredentialModel`: includes the write-only fields the server never returns.
 */
export interface CredentialModelInput {
  /** The model, as runs name it (for example `gpt-5` or `claude-sonnet-4-5`). */
  model?: string;
  /** The name the endpoint knows it by, where that differs (an Azure or Foundry deployment). */
  deploymentName?: string | null;
  /** The context window the endpoint gives it, where that's smaller than the model's own. */
  contextWindowTokens?: number | null;
}

/** Finishes a subscription sign-in: Claude's with the code Anthropic showed, Codex's by polling (no code). The name, description and tag are the new credential's; a sign-in that reconnects a credential keeps its own. */
export interface CredentialSignInFinishRequest {
  /** Format: uuid. */
  signInId?: string;
  /** The code Anthropic shows after signing in to Claude (as shown, `code#state` included). */
  code?: string | null;
  name?: string | null;
  description?: string | null;
  tag?: string | null;
}

/** Where a subscription sign-in stands: still waiting for the person (Codex), or done, with the credential. */
export interface CredentialSignInResult {
  status: CredentialSignInStatus;
  credential: ModelCredential | null;
}

/**
 * A started subscription sign-in: where the person goes to finish it, and the id to finish it with.
 *
 * - Claude: open `CredentialSignInStart.AuthorizeUrl`, sign in, and send back the code Anthropic shows.
 * - Codex: open `CredentialSignInStart.VerificationUrl`, enter `CredentialSignInStart.UserCode`, and poll every `CredentialSignInStart.PollIntervalSeconds` until the sign-in completes.
 */
export interface CredentialSignInStart {
  /** Format: uuid. */
  signInId: string;
  tool: CredentialOAuthTool;
  authorizeUrl: string | null;
  verificationUrl: string | null;
  userCode: string | null;
  pollIntervalSeconds: number | null;
  /** Format: ISO-8601 date-time, up to 7 fractional digits. */
  expiresAtUtc: string;
}

/** Starts a subscription sign-in. */
export interface CredentialSignInStartRequest {
  /**
   * To sign an existing OAuth credential in again (new tokens, same credential and stacks); null for a new one.
   *
   * Format: uuid.
   */
  credentialId?: string | null;
}

/** A subscription sign-in's tokens that you already hold, made into an OAuth credential (or replacing the tokens of one made that way). By default you keep them fresh: the platform never refreshes them, and you send new ones each time you refresh. With `keepFresh`, the platform takes that over. The name, description and tag are the new credential's; replacing tokens keeps the credential's own. */
export interface CredentialSignInTokensRequest {
  /** The coding agent the sign-in is for. */
  tool?: CredentialOAuthTool;
  /** The access token. Write-only. */
  accessToken?: string;
  /** The refresh token, which the coding agent may need during a long run. Write-only. */
  refreshToken?: string;
  /** The OpenID Connect ID token. Required for Codex; null for Claude. Write-only. */
  idToken?: string | null;
  /**
   * When the access token expires (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  expiresAtUtc?: string;
  /** The scopes the tokens carry. */
  scopes?: string[] | null;
  /** The subscription the sign-in belongs to, as the provider names it (for example `max`). */
  subscriptionType?: string | null;
  /** Who signed in, as the provider shows it. */
  accountName?: string | null;
  name?: string | null;
  description?: string | null;
  tag?: string | null;
  /** True: the platform keeps these tokens fresh from now on, with the refresh token, as it does for a sign-in made here. Stop refreshing them yourself: a refresh replaces the refresh token, so only one side can keep doing it. Replacing the tokens of a sign-in you've been refreshing with this set hands it over. Once handed over it can't be handed back; sign in again for new tokens. False (default): you keep them fresh. */
  keepFresh?: boolean;
}

/** One entry of a run's credential stack as it stood when the run started: which credential, and this stack's rules for it. It names the credential but holds none of its secrets; those are read live at each call, so a rotated key is picked up straight away. */
export interface CredentialSnapshotEntry {
  /** Format: uuid. */
  credentialId: string;
  /** The credential's name when the run started, for the run's record. */
  credentialName: string;
  provider: ModelKeyProvider;
  endpointKind: CredentialEndpointKind;
  allowedModels: string[] | null;
  allowedEndpointKinds: CredentialEndpointKind[] | null;
  enabled: boolean;
  /** The hints of the credential's keys when the run started, for the run's record. */
  keyHints: string[];
}

/**
 * A named, ordered list of credentials a run may use (collection `credentialStack`). For each model call the entries are tried in order, skipping any whose rules or models don't fit the chosen model, and failing over to the next when one is rate-limited, failing or refused.
 *
 * A run snapshots the stack when it starts (with `CredentialStack.Version`), so editing a stack never changes a run already going. Every entry names a credential in the stack's own tenant: that's checked when the stack is saved and again when it's resolved.
 */
export interface CredentialStack {
  /** Unique within the tenant; runs can name the stack instead of giving its id. */
  name: string;
  description: string | null;
  entries: CredentialStackEntry[];
  /** Goes up by one on every edit; a run records the version it snapshotted. */
  version: number;
  /** The tenant in the calling system that owns this stack, as `<system>:<id>`; null when the owner isn't known (or the stack is shared). Set once, when the stack is created, and never changed. */
  externalTenantRef: string | null;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** One place in a stack: a credential, plus this stack's own rules for it. The rules can only narrow what the credential allows, never widen it, so the same credential can sit in several stacks with different rules. */
export interface CredentialStackEntry {
  /**
   * A credential in the same tenant as the stack.
   *
   * Format: uuid.
   */
  credentialId: string;
  /** Only these of the credential's models; null for all of them. */
  allowedModels: string[] | null;
  /** Only when the credential's endpoint is one of these kinds; null for any kind. */
  allowedEndpointKinds: CredentialEndpointKind[] | null;
  /** A disabled entry stays in place but is skipped. */
  enabled: boolean;
}

/**
 * One place in a stack: a credential, plus this stack's own rules for it. The rules can only narrow what the credential allows, never widen it, so the same credential can sit in several stacks with different rules.
 *
 * Request shape of `CredentialStackEntry`: includes the write-only fields the server never returns.
 */
export interface CredentialStackEntryInput {
  /**
   * A credential in the same tenant as the stack.
   *
   * Format: uuid.
   */
  credentialId?: string;
  /** Only these of the credential's models; null for all of them. */
  allowedModels?: string[] | null;
  /** Only when the credential's endpoint is one of these kinds; null for any kind. */
  allowedEndpointKinds?: CredentialEndpointKind[] | null;
  /** A disabled entry stays in place but is skipped. */
  enabled?: boolean;
}

/** A credential stack to create, or what an existing one should become (every field is replaced). */
export interface CredentialStackRequest {
  name?: string;
  description?: string | null;
  /** In the order they're tried. Each names a credential in the same tenant. */
  entries?: CredentialStackEntryInput[];
}

/** The credential stack a run uses, captured when it started: the stack, its version, where it was resolved from, and its entries with their rules. Kept with the run as its record of which credentials it was allowed, and used by every model call, resume and child run, so a later edit to the stack never changes a run already going. It never holds a secret. */
export interface CredentialStackSnapshot {
  /** Format: uuid. */
  stackId: string;
  stackName: string;
  stackVersion: number;
  source: CredentialStackSource;
  /** Format: ISO-8601 date-time, up to 7 fractional digits. */
  resolvedAtUtc: string;
  entries: CredentialSnapshotEntry[];
  /**
   * Whether a run started by this one inherits the stack. Only a stack chosen explicitly (at the start, or inherited from one that was) is handed down; a default isn't, so a child resolves its own defaults.
   *
   * Computed by the server; ignored on input.
   */
  readonly passesToChildren: boolean;
}

/** Where a credential stack is used, as defaults and by knowledge bases. While any of these use it, it can't be deleted. Runs and automations that name it aren't counted. */
export interface CredentialStackUsage {
  /**
   * The stack's id.
   *
   * Format: uuid.
   */
  credentialStackId: string;
  /** It's the tenant's default stack. */
  tenantDefault: boolean;
  /** The namespaces whose default it is. */
  namespaces: CredentialStackUser[];
  /** The knowledge bases (partitions) that embed with it, up to 500. */
  partitions: CredentialStackUser[];
}

/** A namespace or knowledge base that uses a credential stack. */
export interface CredentialStackUser {
  /**
   * Its id.
   *
   * Format: uuid.
   */
  id: string;
  /** Its name. */
  name: string;
}

/** What a test of a credential found: each key was used to list the provider's models at the credential's endpoint. The test passes when every key does; a passing test switches a credential its circuit breaker turned off back on. */
export interface CredentialTestResult {
  /** Format: uuid. */
  credentialId: string;
  succeeded: boolean;
  /** The first failing key's code (`CredentialErrorCodes`); null when the test passed. */
  errorCode: string | null;
  /** Format: ISO-8601 date-time, up to 7 fractional digits. */
  testedAtUtc: string;
  keys: CredentialKeyTestResult[];
}

/** A schedule that triggers an automation: a cron expression split into fields, in UTC. A field left out means "every" (`*`). */
export interface CronSchedule {
  /**
   * The schedule's id.
   *
   * Format: uuid.
   */
  id: string;
  /** A name for the schedule. Optional. */
  name: string | null;
  /** Whether the schedule triggers the automation. Switch it off to pause it without deleting it. */
  isEnabled: boolean;
  /** The cron seconds field. Optional: set it for a six-field expression. */
  second: string | null;
  /** The cron minutes field, such as `0` or `*\/15`. */
  minute: string;
  /** The cron hours field, in UTC, such as `7`. */
  hour: string;
  /** The cron day-of-month field. */
  dayOfMonth: string;
  /** The cron month field. */
  month: string;
  /** The cron day-of-week field, such as `1-5` for weekdays. */
  dayOfWeek: string;
  /**
   * When the schedule next triggers, in UTC. Set by Maitento.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  nextOccurrence: string | null;
}

/**
 * A schedule that triggers an automation: a cron expression split into fields, in UTC. A field left out means "every" (`*`).
 *
 * Request shape of `CronSchedule`: includes the write-only fields the server never returns.
 */
export interface CronScheduleInput {
  /**
   * The schedule's id.
   *
   * Format: uuid.
   */
  id?: string;
  /** A name for the schedule. Optional. */
  name?: string | null;
  /** Whether the schedule triggers the automation. Switch it off to pause it without deleting it. */
  isEnabled?: boolean;
  /** The cron seconds field. Optional: set it for a six-field expression. */
  second?: string | null;
  /** The cron minutes field, such as `0` or `*\/15`. */
  minute?: string;
  /** The cron hours field, in UTC, such as `7`. */
  hour?: string;
  /** The cron day-of-month field. */
  dayOfMonth?: string;
  /** The cron month field. */
  month?: string;
  /** The cron day-of-week field, such as `1-5` for weekdays. */
  dayOfWeek?: string;
  /**
   * When the schedule next triggers, in UTC. Set by Maitento.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  nextOccurrence?: string | null;
}

/** Who the caller is (`GET /users/self`): their user, their tenant, and the roles this session or API key is authorised with. */
export interface CurrentUserResponse {
  /** The calling user. */
  user: User;
  /** The caller's tenant. */
  tenant: CurrentUserTenant;
  /** The roles this session or API key is authorised with, such as `Tenant.Admin` or `Tenant.User`. */
  roles: string[];
  /** Whether this session belongs to one of the platform's own administrators. Always false for an API key. */
  isSuperAdmin: boolean;
}

/** The tenant the calling user belongs to, as returned by `GET /users/self`. */
export interface CurrentUserTenant {
  /**
   * The tenant's id.
   *
   * Format: uuid.
   */
  id: string;
  /** The tenant's display name. */
  name: string;
}

/** The stack runs use when nothing more specific names one: for the tenant, or for one namespace. Null for none. */
export interface DefaultCredentialStack {
  /** Format: uuid. */
  credentialStackId: string | null;
}

/**
 * The stack runs use when nothing more specific names one: for the tenant, or for one namespace. Null for none.
 *
 * Request shape of `DefaultCredentialStack`: includes the write-only fields the server never returns.
 */
export interface DefaultCredentialStackInput {
  /** Format: uuid. */
  credentialStackId?: string | null;
}

/** A tool call that waits its turn: when a model asks for several tool calls at once and one of them needs approval, the calls after it wait here and run, in order, once that approval is decided. */
export interface DeferredToolCall {
  /** The model's id for the call. */
  toolCallId: string;
  /** The name of the tool the model called. */
  functionName: string;
  /** The arguments the model gave, as JSON text. */
  argumentsJson: string;
  /**
   * The id of the agent that made the call.
   *
   * Format: uuid.
   */
  agentId: string;
  /** The name of the participant that made the call. */
  agentName: string;
}

/** The body of a 422 for an uploaded file Maitento could not read usable text from, even after trying OCR where it could. The failure is permanent for that file: don't retry the upload, show the guidance instead. */
export interface DocumentTextExtractionFailedResponse {
  /** What went wrong, in English. */
  error: string;
  /** The kind of failure: always `DocumentTextExtractionFailed`. */
  category: string;
  /** Whether Maitento tried reading the file with OCR (text recognition) before giving up. */
  ocrAttempted: boolean;
  /** What the person who uploaded the file can do about it, such as uploading a text-searchable PDF instead. */
  guidance: string;
}

/** A single edit operation to perform on a file. Supports multiple edit types: find/replace, line-range replacement, insert, and delete. */
export interface EditOperation {
  /** Operation type: "replace" (find/replace), "replaceLines", "insertAfter", "deleteLines". */
  type?: string;
  /**
   * String to find (for a `replace` operation).
   *
   * Sent as-is: the server does not trim it.
   */
  find?: string | null;
  /**
   * String to replace with (for a `replace` operation).
   *
   * Sent as-is: the server does not trim it.
   */
  replace?: string | null;
  /** Replace all occurrences, not just first (for a `replace` operation). Default false. */
  replaceAll?: boolean;
  /** Start line number, 1-based (for a `replaceLines` operation). */
  startLine?: number | null;
  /** End line number, 1-based, inclusive (for a `replaceLines` operation). */
  endLine?: number | null;
  /**
   * New content to replace lines with (for a `replaceLines` or `insertAfter` operation).
   *
   * Sent as-is: the server does not trim it.
   */
  content?: string | null;
  /** Insert new content after this line number, 1-based (for an `insertAfter` operation). Use 0 to insert at the beginning of the file. */
  insertAfterLine?: number | null;
  /** Line numbers to delete, 1-based (for a `deleteLines` operation). */
  deleteLines?: number[] | null;
}

/** Result of a single edit operation. */
export interface EditOperationResult {
  /** Whether the operation succeeded. */
  success: boolean;
  /** Error message if operation failed. */
  error: string | null;
  /** Number of replacements made (for a `replace` operation with `replaceAll` true). */
  replacementCount: number;
}

/** Request for editing a file with one or more operations. Supports find/replace, line-range edits, insertions, and deletions. Designed for AI agents that need to modify files programmatically. */
export interface EditRequest {
  /** Path to the file within the file system. */
  path?: string;
  /** List of edit operations to apply, in order. */
  operations?: EditOperation[];
}

/** What an edit did, operation by operation, and the file after it. */
export interface EditResponse {
  /** Whether all operations succeeded. */
  success: boolean;
  /** Results for each operation. */
  operationResults: EditOperationResult[];
  /** The file after edits were applied. */
  file: FileSystemFile | null;
}

/** What a tenant is entitled to right now: its plan's terms, with any terms agreed for this tenant applied on top. Everything that limits or prices work reads this. Null on a limit means unlimited. */
export interface EffectiveEntitlements {
  /**
   * The tenant these are for.
   *
   * Format: uuid.
   */
  tenantId: string;
  /** The plan. */
  tier: SkuTier;
  /** Whether the plan is paid monthly or annually. */
  cadence: BillingCadence;
  /** The currency the tenant is billed in. */
  currency: string;
  /** `Frozen` after a failed renewal payment, until it's paid or the time to pay runs out. */
  status: ContractStatus;
  /** The version of the plan definitions these terms come from. */
  skuCatalogueVersion: number;
  /** The version of the price list these prices come from. */
  priceBookVersion: number;
  /**
   * The instant the tenant's billing months are counted from.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  billingAnchorUtc: string;
  /** What the plan includes each billing month, per meter. */
  allowances: MeterAllowances;
  /** How much the tenant may store at once, in GB. */
  storageCapGb: number | null;
  /** How many runs of each kind may run at once. */
  lanes: EffectiveLane[];
  /** The most knowledge bases (temporary ones included) the tenant may hold. */
  maxPartitions: number | null;
  /** The most file systems the tenant may hold. */
  maxFileSystems: number | null;
  /** The most model credentials the tenant may hold. */
  maxCredentials: number | null;
  /** The most credential stacks the tenant may hold. */
  maxCredentialStacks: number | null;
  /** How long a finished run is kept, in hours, unless it's retained. Never more than `EffectiveEntitlements.RetentionMaxHours`. */
  retentionDefaultHours: number;
  /** The longest a run can be kept, in hours. */
  retentionMaxHours: number | null;
  /** The discount on work beyond the allowances, in hundredths of a percent (1500 is 15%). */
  overageDiscountBasisPoints: number;
  /** Where the tenant's work waits relative to others' when the platform is busy. */
  priority: QueuePriorityClass;
  /** The plan includes sandboxes (capsules) and code pipelines. */
  premiumExecution: boolean;
  /** The plan can buy credit (top-ups and automatic top-ups). */
  canTopUp: boolean;
  /** The subscription price per month on the contract's cadence. */
  planPricePerMonth: number;
  /** The subscription price per month, billed annually. */
  planPriceAnnualPerMonth: number;
  /** The subscription price per month, billed monthly. */
  planPriceMonthly: number;
  /** What work beyond the allowances costs, per meter. */
  rates: MeterRates;
  /** How many fetch units a page costs, by how it's fetched. */
  webFetchUnits: WebFetchUnitTable;
  /** The price of one more lane of each type the tenant can buy on its tier. */
  lanePrices: LaneAddOnPrice[];
}

/** A tenant's concurrency on one lane type: what the tier includes, what was bought, the ceiling, and the resulting limit. Null means unlimited. */
export interface EffectiveLane {
  /** The kind of run: standard (interactions and apps), sandboxes (capsules) or code pipelines. */
  lane: LaneType;
  /** How many the plan includes. */
  included: number | null;
  /** How many more were bought. */
  purchased: number;
  /** The most the plan can have. */
  max: number | null;
  /** How many may run at once: what's included plus what was bought, up to the most. */
  limit: number | null;
}

/** Searches a partition's files for passages whose meaning is close to a query. */
export interface EmbeddedVectorSearchRequest {
  /**
   * What to search for, in plain words.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  query: string;
  /**
   * The partition (knowledge base) to search.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   * Format: uuid.
   */
  partitionId: string;
}

/** One embedding model Maitento can index and search with, and the limits that decide how text is cut into chunks before it reaches it. The limits differ per model because their input ceilings differ (for example, `gemini-embedding-001` accepts 2,048 tokens where `text-embedding-3-large` accepts 8,191). */
export interface EmbeddingModelDefinition {
  /** The provider that serves the model. */
  provider: EmbeddingProvider;
  /** The provider's model id (for example `text-embedding-3-large`). */
  model: string;
  /** The width the model produces when no output width is requested. */
  nativeDimensions: number;
  /** The output widths a partition may be indexed at with this model. */
  supportedDimensions: number[];
  /** The provider's hard input ceiling for one embedding call, in the model's own tokens. */
  maxInputTokens: number;
  /** The chunk size used when a partition's profile does not choose one. */
  defaultChunkSizeTokens: number;
  /** The overlap between consecutive chunks used when a partition's profile does not choose one. */
  defaultChunkOverlapTokens: number;
  /** The largest chunk size a profile may choose for this model. */
  maxChunkSizeTokens: number;
  /** Whether this is the default: the model every partition without a profile of its own embeds with. Exactly one listed model is the default. */
  isDefault: boolean;
  /** True for a model Maitento no longer offers, which a partition was indexed with before it was withdrawn. The partition can still be read, searched and re-indexed, but a new profile cannot choose it: move the partition to a listed model. */
  isWithdrawn: boolean;
  /** True for your own model rather than one Maitento lists: a model id served by one of the providers' APIs, typically an OpenAI-compatible endpoint of yours, whose width a test call measured. Its limits are the most conservative of any model, it embeds at its natural width, and it never falls back to Maitento's key. */
  isCustom: boolean;
  /**
   * The most words one embedding call may carry for this model: 4,000 for an 8,191-token model, and in proportion for others.
   *
   * Computed by the server; ignored on input.
   */
  readonly maxWordsPerEmbedding: number;
  /**
   * Above this many words a document is chunked rather than embedded whole: at most 750, and never more than one call can carry.
   *
   * Computed by the server; ignored on input.
   */
  readonly wholeDocumentMaxWords: number;
  /**
   * Above this many characters a document is chunked rather than embedded whole: at most 30,000, and fewer for a model with a small input ceiling.
   *
   * Computed by the server; ignored on input.
   */
  readonly wholeDocumentMaxCharacters: number;
}

/** One passage a search found, with the file it came from. Results come best match first. */
export interface EmbeddingsSearchResult {
  /**
   * The file's id.
   *
   * Format: uuid.
   */
  id: string;
  /** The file's name. */
  name: string;
  /** The file's MIME type. */
  contentType: string;
  /** The file's size, in bytes. */
  size: number;
  /** What kind of document the file is. */
  type: IngestedFileType;
  /** The matching passage, cut to 1,000 characters. */
  text: string;
  /** How well the passage matches the query: higher is better. */
  score: number;
}

/** One run an automation started, or tried to start: what triggered it and how it ended. */
export interface ExecutionHistoryEntry {
  /**
   * The entry's id.
   *
   * Format: uuid.
   */
  id: string;
  /** What triggered the automation: a schedule, a message trigger, or a manual trigger. */
  triggerType: ExecutionTriggerType;
  /**
   * The id of the schedule or message trigger that fired. Null for a manual trigger.
   *
   * Format: uuid.
   */
  triggerId: string | null;
  /**
   * The id of the automation's action that started the run.
   *
   * Format: uuid.
   */
  actionId: string;
  /**
   * The run it started. An all-zero id when the run could not be started (`errorMessage` says why).
   *
   * Format: uuid.
   */
  processId: string;
  /** What kind of run `processId` is. */
  processType: ProcessType;
  /**
   * When the run was started, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateStarted: string;
  /**
   * When the run ended, in UTC. Null while it is still going.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCompleted: string | null;
  /** How the run ended, or `Pending` while it is still going. */
  outcome: ExecutionOutcome;
  /** Why the run could not be started. Null otherwise: read the run itself for why it failed. */
  errorMessage: string | null;
}

/**
 * A tool (external operation): what an agent sees and calls. It points at one version of a connector, tells the model when to use it, fixes values the model must not choose, and can require a person's approval. Each change adds a new version, and agents, interactions, apps and code pipelines keep calling the version they were built against.
 *
 * Discriminated by `$type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type ExternalOperation =
  | McpExternalOperation
  | OpenApiExternalOperation;

/** A file's content as bytes. */
export interface FileByteContentRequest {
  /**
   * The file's bytes, up to 100 MB. May be empty.
   *
   * Validation: maxLength: 100000000; required (empty or whitespace-only strings are rejected).
   * Format: base64.
   */
  content: string;
}

/** A file's content as lines of text. */
export interface FileLinesContentRequest {
  /**
   * The file's lines, up to 100,000. May be empty.
   *
   * Sent as-is: the server does not trim it.
   * Validation: maxLength: 100000; required (empty or whitespace-only strings are rejected).
   */
  content: string[];
}

/** A directory in a file system listing. */
export interface FileSystemDirectory {
  /** Discriminator: always `"directory"` for this type; send it as the first property. */
  $type: "directory";
  /** The entry's name. */
  name: string;
  /** The entry's full path within the file system. */
  path: string;
  /**
   * When it was created (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last modified (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateModified: string;
}

/**
 * An entry in a file system directory listing: a file or a directory.
 *
 * Discriminated by `$type`, which must be the FIRST property of the JSON object sent to the server.
 */
export type FileSystemEntry =
  | FileSystemDirectory
  | FileSystemFile;

/** A file in a file system listing. */
export interface FileSystemFile {
  /** Discriminator: always `"file"` for this type; send it as the first property. */
  $type: "file";
  /** The file's size, in bytes. */
  size: number;
  /** The entry's name. */
  name: string;
  /** The entry's full path within the file system. */
  path: string;
  /**
   * When it was created (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last modified (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateModified: string;
}

/** A file's content as text. */
export interface FileTextContentRequest {
  /**
   * The file's text, up to 100 MB. Whitespace is kept exactly as sent.
   *
   * Sent as-is: the server does not trim it.
   * Validation: maxLength: 100000000; required (empty or whitespace-only strings are rejected).
   */
  content: string;
}

/** The text extracted from a file. */
export interface FileTextResponse {
  /** The file's extracted text. */
  text: string;
}

/** Request for finding files with optional glob pattern and content search. Designed for AI agents that need to explore and search filesystems efficiently. */
export interface FindRequest {
  /** Starting directory path. Defaults to "/" (root). */
  path?: string;
  /** Glob pattern to match files (e.g., "**\/*.cs", "src/**\/*.ts"). Supports *, **, ?, [abc], {a,b} patterns. */
  pattern?: string | null;
  /** Search pattern for file contents. If specified, only files containing this pattern are returned. */
  grep?: string | null;
  /** How to interpret the grep pattern: "literal" (default) or "regex". */
  grepMode?: string;
  /** Case-insensitive search for grep. Default false. */
  ignoreCase?: boolean;
  /** Number of lines before and after each grep match to include as context. */
  contextLines?: number;
  /** If true, include a preview of each file's content (first N lines). */
  includePreview?: boolean;
  /** Number of lines to include in preview. Default 30. */
  previewLines?: number;
  /** Maximum number of results to return. Default 100. */
  maxResults?: number;
  /** Maximum recursion depth. Default -1 (unlimited). */
  maxDepth?: number;
  /** Filter by entry type: "file", "directory", or "all". Default "file". */
  type?: string;
  /** Include hidden files/directories (starting with .). Default false. */
  includeHidden?: boolean;
}

/** The files and directories a find matched. */
export interface FindResponse {
  /** The matching files/directories. */
  results: FindResultEntry[];
  /** Total number of matches found (may be more than `results` holds, when it was cut short). */
  totalFound: number;
  /** True if `results` was cut short at `maxResults`. */
  truncated: boolean;
}

/** One file or directory a find matched. */
export interface FindResultEntry {
  /** Full path to the file or directory within the file system. */
  path: string;
  /** Entry type: "file" or "directory". */
  type: string;
  /** File size in bytes (0 for directories). */
  size: number;
  /**
   * When it was last modified (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateModified: string;
  /** Grep matches found in this file. Null if `grep` was not specified. */
  grepMatches: GrepMatch[] | null;
  /** Preview of file content (the first `previewLines` lines). Null if `includePreview` was false. */
  preview: string | null;
}

/** Represents a single grep match within a file. */
export interface GrepMatch {
  /** 1-based line number where the match was found. */
  line: number;
  /** The full content of the matching line. */
  content: string;
  /** Lines before the match (context). Empty if contextLines was 0. */
  before: string[];
  /** Lines after the match (context). Empty if contextLines was 0. */
  after: string[];
}

export interface HttpMethod {
  method?: string;
}

/** A file uploaded to a partition (or downloaded into one by an agent's web tools): its extracted text, and how far it has got through being described, chunked and embedded for search. */
export interface IngestedFile {
  /** The file's name. */
  name: string;
  /** The file's MIME type, such as `application/pdf`. */
  contentType: string;
  /** The file's size, in bytes. */
  size: number;
  /** What kind of document it is, which decides how its text is extracted. */
  type: IngestedFileType;
  /** The text extracted from the file. */
  text: string;
  /** True while an image is waiting to be described in words, so it can be searched. */
  isImageDescriptionRequired: boolean;
  /**
   * When the image was described (UTC). Null for other files, and until it has been.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  imageDescriptionTime: string | null;
  /** Not used: always false. */
  isTrainingDataGenerated: boolean;
  /**
   * Not used: always null.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  trainingDataTime: string | null;
  /** True once the file has been embedded and can be found by search. */
  isVectorGenerated: boolean;
  /**
   * When the file was last embedded (UTC). Null until it has been.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  vectorGenerationTime: string | null;
  /** Why the file cannot be indexed until someone acts, such as no embedding key for its knowledge base. Null while it is being indexed, once it is, and when its content changes. Search of a knowledge base that cannot embed is refused with the same code. */
  indexingFailure: IngestedFileIndexingFailure | null;
  /** The provider, model and width (`provider/model@width`) the file's current embedding was made with. Null until it is embedded. While a partition is re-indexed, a file counts as done once this matches the partition's new profile. */
  embeddingModelKey: string | null;
  /** True while the file is waiting to be split into chunks before it is embedded. False once it has been, and for a file short enough to be embedded whole. */
  isChunkingRequired: boolean;
  /**
   * When the file was split into chunks (UTC). Null until it has been, or if it did not need to be.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  chunkGenerationTime: string | null;
  /**
   * The partition the file belongs to.
   *
   * Format: uuid.
   */
  partitionId: string;
  /** True for a file in a temporary partition: it is never indexed or searchable, raises no webhooks, and is removed once `expiresAt` has passed. False on every file of an ordinary partition. */
  isTemporary: boolean;
  /**
   * When a temporary file is removed (UTC). Null on every file of an ordinary partition.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  expiresAt: string | null;
  /** Where a web download came from. Null on every uploaded file. */
  webSource: IngestedFileWebSource | null;
  /** The file's version: 1 on upload, and one more each time its content is replaced with something different. */
  version: number;
  /**
   * The id of the user who created it. A call made with an API key is recorded as the key's user.
   *
   * Format: uuid.
   */
  userCreatedById: string;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** Why a file cannot be indexed (made searchable) until someone acts: no embedding key for its knowledge base's provider, or every key failed. Fixing the cause (adding a model key, say) gets the file indexed, which clears this. A file whose knowledge base has no key at all waits rather than being retried, and is picked up again as soon as a key or consent to Maitento's key is added. */
export interface IngestedFileIndexingFailure {
  /** The stable code: `api:embeddings:fallback-not-permitted` (no key, and Maitento's own may not be used) or `api:embeddings:credentials-exhausted` (every key failed). */
  code: string;
  /** What is wrong and how to fix it, for a person. */
  message: string;
  /**
   * When it was first recorded for the file's current content.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateFailed: string;
}

/** A file as a partition's file listing returns it: everything about the file and how far it has got through processing, without the extracted `text` (which can be megabytes). Read `GET /files/by-id/{id}` for that. */
export interface IngestedFileListItem {
  /**
   * The file's id.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * The tenant that owns the file.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The user who uploaded the file.
   *
   * Format: uuid.
   */
  userCreatedById: string;
  /**
   * The partition the file belongs to.
   *
   * Format: uuid.
   */
  partitionId: string;
  /** The file's name. */
  name: string;
  /** The file's MIME type. */
  contentType: string;
  /** The file's size, in bytes. */
  size: number;
  /** What kind of document it is. */
  type: IngestedFileType;
  /** The file's version: 1 on upload, and one more each time its content is replaced with something different. */
  version: number;
  /**
   * When the file was uploaded (UTC).
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When the file last changed (UTC), including progress through processing.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
  /** True while an image is waiting to be described in words, so it can be searched. */
  isImageDescriptionRequired: boolean;
  /**
   * When the image was described (UTC). Null for other files, and until it has been.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  imageDescriptionTime: string | null;
  /** Not used: always false. */
  isTrainingDataGenerated: boolean;
  /**
   * Not used: always null.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  trainingDataTime: string | null;
  /** True once the file has been embedded and can be found by search. */
  isVectorGenerated: boolean;
  /**
   * When the file was last embedded (UTC). Null until it has been.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  vectorGenerationTime: string | null;
  /** Why the file cannot be indexed until someone acts (see `IngestedFile.IndexingFailure`). */
  indexingFailure: IngestedFileIndexingFailure | null;
  /** True while the file is waiting to be split into chunks before it is embedded. */
  isChunkingRequired: boolean;
  /**
   * When the file was split into chunks (UTC). Null until it has been, or if it did not need to be.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  chunkGenerationTime: string | null;
  /** True for a temporary partition's file: never indexed, and removed at `expiresAt`. */
  isTemporary: boolean;
  /**
   * When a temporary file is removed (UTC). Null on every file of an ordinary partition.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  expiresAt: string | null;
  /** Where a web download came from; null for an uploaded file. */
  webSource: IngestedFileWebSource | null;
}

/** One page of a partition's files, newest first. Pass `nextCursor` back as `cursor` for the next page. */
export interface IngestedFilePage {
  /** The files on this page. */
  items: IngestedFileListItem[];
  /** The cursor for the next page, passed back as it is; null on the last page. */
  nextCursor: string | null;
}

/** A file's name, size and type. */
export interface IngestedFileSummary {
  /** The file's name. */
  name: string;
  /** The file's size, in bytes. */
  size: number;
  /** What kind of document it is. */
  type: IngestedFileType;
}

/** Where a web download came from, and which run's agent fetched it. Null on every uploaded file. */
export interface IngestedFileWebSource {
  /** The URL the agent asked for. */
  url: string;
  /** The URL the content came from after redirects, when it differs. */
  finalUrl: string | null;
  /** The page's or document's title, when it has one. */
  title: string | null;
  /** What the URL turned out to be, which decides how it was turned into text. */
  kind: WebContentKind;
  /** How the content was obtained. */
  route: WebFetchRoute;
  /** The kind of run whose agent fetched it. */
  processType: ProcessType;
  /**
   * The run whose agent fetched it.
   *
   * Format: uuid.
   */
  processId: string;
  /** The agent that fetched it, when known. */
  agentName: string | null;
  /** The extracted text was longer than a file may hold and was cut short. */
  isTextCapped: boolean;
}

/** A model you define in full when you start a run, for one that isn't in Maitento's catalogue, such as a model on your own endpoint. Nothing is stored: only that run uses it. Its key and endpoint are not here: give them in the start request's `credentials`, with a `provider` that matches this model's `credentialProvider`. */
export interface InlineAiModelDefinition {
  /** A display name for the model, shown in logs and token usage. */
  name: string;
  /** The protocol the endpoint speaks: `"OpenAi"` or `"Anthropic"`. */
  apiType: string;
  /** The model id sent to the endpoint, exactly as the provider expects it. */
  modelIdentifier: string;
  /** A name of your own for this model's key: the start request's `credentials` whose `provider` matches it are used. A model defined inline never falls back to Maitento's own key. */
  credentialProvider: string;
  /** The model's context window, in tokens. */
  contextWindowTokens: number;
  /** The most the model may write in one reply, in tokens. */
  maxOutputTokens: number;
  /** Whether the endpoint accepts `response_format=json_schema`. False makes Maitento use `json_object` and restate the schema in the prompt instead. Default: true; send the real answer for your endpoint. */
  supportsJsonSchemaResponseFormat: boolean;
  /** Which tokenizer to estimate the model's token counts with. Null: worked out from the model's name. */
  tokenizerFamily: string | null;
  /** The `reasoning_effort` sent with every request. Set it for a reasoning model whose own default doesn't work with tool calls, since every interaction sends tools. Null: not sent. */
  reasoningEffort: string | null;
}

