/** A run of an interaction: what it was started with, where it has got to, the whole conversation and its answer. */
export interface InteractionProcess {
  /** The interaction, and the version of it, that this run runs. */
  interaction: VersionReference;
  /**
   * When the run started (UTC). Null until it does.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateStarted: string | null;
  /**
   * When the run ended (UTC). Null while it is still going.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateEnded: string | null;
  /**
   * How long the run has spent working, not counting time spent waiting for a person. While the run is `Running`, add the time since `dateRunnerClaimed` for the current stretch.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  executionTime: DotNetTimeSpan;
  /** The inputs the run was started with. */
  inputs: NameValuePair[];
  /** The run's answer: text, or JSON matching the interaction's schema (or `responseJsonSchema`). Null until there is one. */
  output: string | null;
  /** Why the run failed or was stopped, as text. Null when it has not. */
  failureDetails: string | null;
  /** Where the run has got to: waiting to start, running, waiting (for a person, an approval or its sub-interactions), or ended. */
  status: InteractionProcessStatus;
  /** The run's conversation: every message, tool call and result, grouped by kind. Sort the items by `sequence` to read them in order. */
  context: InteractionProcessContext;
  /**
   * When the worker running the run last reported that it was still working (UTC). Null before a worker picks it up.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRunnerPing: string | null;
  /**
   * When a worker last picked the run up (UTC): the start of its current stretch of work. A run that resumes after waiting for a person gets a new value, and `executionTime` holds the time worked before it. Null until a worker picks the run up.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateRunnerClaimed: string | null;
  /**
   * When the run started waiting for a lane, in UTC; null when it isn't waiting. A waiting run is in status New, and `GET /processes/{type}/{id}/lane` says why it waits.
   *
   * Computed by the server; ignored on input.
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  readonly waitingForLaneSinceUtc: string | null;
  /** The name of the worker that last ran the run, for diagnostics. Null until a worker picks it up. */
  hostname: string | null;
  /**
   * The run that started this one: an app run, or the interaction run whose participant started this sub-interaction. Null when no other run started it.
   *
   * Format: uuid.
   */
  parentProcessId: string | null;
  /** What kind of run `parentProcessId` is. Null exactly when that is null. */
  parentProcessType: ProcessType | null;
  /**
   * The run at the top of the tree this run belongs to: the same for every run in the tree, so you can group them without following parent links. Null when no other run started this one.
   *
   * Format: uuid.
   */
  rootProcessId: string | null;
  /**
   * The automation that started this run (on its schedule, from a message, or by hand), or null when something else started it.
   *
   * Format: uuid.
   */
  triggeredByAutomatedActionId: string | null;
  /** The automation's name at the time it started this run. Null exactly when `triggeredByAutomatedActionId` is. */
  triggeredByAutomatedActionName: string | null;
  /** True while a retention lease keeps this run: its own, or one inherited from a retained run that started it. A retained run is never deleted when the tenant's retention period ends. Null or false: not retained. */
  retentionLeaseActive: boolean | null;
  /**
   * When the lease was taken, in UTC. For an inherited lease, when the ancestor's lease was taken.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  retentionLeaseAppliedAtUtc: string | null;
  /**
   * The id of the user who took the lease.
   *
   * Format: uuid.
   */
  retentionLeaseAppliedByUserId: string | null;
  /** The name of the user who took the lease, as it was when they took it. */
  retentionLeaseAppliedByUserName: string | null;
  /** Why it is retained, as the person who retained it wrote it (optional, at most 500 characters). */
  retentionLeaseNote: string | null;
  /**
   * Null when the lease is this run's own. Otherwise the id of the ancestor run whose lease keeps this one; releasing that run's lease releases this one too.
   *
   * Format: uuid.
   */
  retentionLeaseInheritedFromProcessId: string | null;
  /** When the run ended because a person did not reply in time: the status it was waiting in. Null otherwise. */
  beforeTimeoutStatus: InteractionProcessStatus | null;
  /** A JSON Schema the run's answer must match in place of the interaction's own, as given when the run started. Null: the interaction's schema applies. */
  responseJsonSchema: string | null;
  /** The tool call waiting for a person's approval, while the run is `PendingApproval`. Null otherwise. */
  pendingApproval: PendingToolCallApproval | null;
  /** Tool calls the model asked for in the same reply as the one awaiting approval. They run, in order, once that approval is decided. Null when there are none. */
  deferredToolCalls: DeferredToolCall[] | null;
  /** The names of tools this run's agents are not given, as listed when the run started. */
  disabledTools: string[] | null;
  /**
   * The temporary knowledge base (partition) the run's web fetches are kept in: the one given when the run started, else the namespace's default, else the tenant's. Runs it starts use it too. Null: no agent of this run may fetch.
   *
   * Format: uuid.
   */
  webDownloadPartitionId: string | null;
  /** The run's per-agent overrides of the agents' web tools, as given when it started. */
  webAccessOverrides: WebAccessOverride[] | null;
  /** Which loom each agent of the run wakes up with, settled when the run started. */
  looms: LoomMapping[];
  /** Threads handed to the run's agents when it started, which each agent learns the first time it wakes. */
  loomGifts: LoomStartGift[];
  /** The agents of this run that use a different model from the one their definition names. */
  aiModelOverrides: AiModelOverride[];
  /**
   * The longest this run may take: the limit given when it started (or by the run that started it), else the interaction's own. The run stops with an error when it is reached; time spent waiting for a person does not count. Null: no limit.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationAutoTermination: DotNetTimeSpan | null;
  /**
   * How long into the run the agents are told that time is running short: the value given when it started, else the interaction's own. Null: they are not told.
   *
   * Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
   */
  durationWarningToAi: DotNetTimeSpan | null;
  /** The tokens the run's model calls used: one record per turn, or more when a turn moved to another key or model. A turn's record is updated as the turn goes, and is complete once its `finished` is true. */
  tokenUsage: InteractionProcessTokenUsage[];
  /** For participants whose agent is a router: which agent took each turn, and why, oldest first. */
  routingDecisions: InteractionRoutingDecision[];
  /** In a managed interaction: a dispatch held up by a person's approval of a tool call the dispatched agent made. It is finished first when the run resumes. Null otherwise. */
  managedDispatch: InteractionProcessManagedDispatch | null;
  /** This run's place in a tree of sub-interactions: present when its interaction lets participants start them, and on every run one of them started. Null otherwise. */
  swarm: InteractionProcessSwarm | null;
  /** The model provider keys the run was started with (the keys themselves are never returned). Calls use these first, then your tenant's model keys. Empty when none were given. */
  credentials: InteractionProcessCredential[];
  /** Whether an agent may fall back to Maitento's own key once your keys for its provider are used up or have failed (and only when your tenant allows it). Null or false: it may not, and the turn fails instead. */
  allowMaitentoFallback: boolean | null;
  /** The credential stack the run uses, as it stood when the run started: which stack, its version, where it was resolved from, and its entries and rules. No secrets: keys are read live at each call. When set, every model call uses only this stack. Null: the run uses the credentials it was started with and the tenant's model keys. */
  credentialStack: CredentialStackSnapshot | null;
  /** Keys that failed during the run and were skipped: which, why and when. */
  credentialFailures: InteractionProcessCredentialFailure[];
  /**
   * The id of the user who created it. A call made with an API key is recorded as the key's user.
   *
   * Format: uuid.
   */
  userCreatedById: string;
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** An interaction run's conversation, grouped by kind of item. Every item has a `sequence`: merge the lists and sort by it to read the conversation in order. */
export interface InteractionProcessContext {
  /** What the agents said. */
  agentMessage: InteractionProcessContextAgentMessage[];
  /** Votes for a vote proposal or a proposed final answer. */
  agree: InteractionProcessContextAgree[];
  /** Answers to questions one agent asked another directly. */
  directQuestionAnswer: InteractionProcessContextDirectQuestionAnswer[];
  /** Questions one agent asked another directly. */
  directQuestionAsk: InteractionProcessContextDirectQuestionAsk[];
  /** Votes against a vote proposal or a proposed final answer, with the reasons. */
  disagree: InteractionProcessContextDisagree[];
  /** Messages people sent to the run. */
  humanMessage: InteractionProcessContextHumanMessage[];
  /** System messages added to the run while it was going. */
  injectedSystemMessage: InteractionProcessContextInjectedSystemMessage[];
  /** Turns an agent passed without saying anything. */
  noAction: InteractionProcessContextNoAction[];
  /** Messages from Maitento running the conversation, such as handing an agent its turn. */
  orchestratorMessage: InteractionProcessContextOrchestratorMessage[];
  /** Final answers the agents proposed. */
  solutionProposal: InteractionProcessContextSolutionProposal[];
  /** System prompts the agents were given. */
  systemPrompt: InteractionProcessContextSystemPrompt[];
  /** Tool calls the agents made. */
  toolCall: InteractionProcessContextToolCall[];
  /** The results of the agents' tool calls. */
  toolResult: InteractionProcessContextToolResult[];
  /** Things the agents put to a vote. */
  voteProposal: InteractionProcessContextVoteProposal[];
  /** Summaries of the earlier conversation, written when it neared the model's context window. */
  summary: InteractionProcessContextSummary[];
}

