  description: string;
  /**
   * The JSON Schema of the request body, as text. The model's arguments are checked against it before a call is made. Omitted: no body is sent.
   *
   * Sent as-is: the server does not trim it.
   */
  requestSchemaJson?: string | null;
  /**
   * The JSON Schema the endpoint's response must match, as text. Omitted: the response is not checked.
   *
   * Sent as-is: the server does not trim it.
   */
  responseSchemaJson?: string | null;
  /**
   * The kind of credential the endpoint needs. The credential itself is given where a tool uses the connector.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  authenticationType: ConnectorAuthenticationType;
  /** Whether to replace typographic characters in the response (curly quotes, dashes, bullets, the ellipsis) with plain ones before it is read. Defaults to false. */
