/** One night's weaving of a loom: consolidation that runs in the background once its conversations go quiet. It records what it did, the dream log it wrote, and the tokens it spent. */
export interface NightWeaving {
  /**
   * The loom that was woven.
   *
   * Format: uuid.
   */
  loomId: string;
  /** Whether it is still running, completed or failed. */
  status: NightWeavingStatus;
  /**
   * When it finished (UTC), whether it completed or failed. Null while it is running.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCompleted: string | null;
  /**
   * The interaction run whose model credentials the weaving used, and to which its usage is attributed.
   *
   * Format: uuid.
   */
  sourceInteractionProcessId: string | null;
  /**
   * The sessions (`LoomSession`) it consolidated.
   *
   * Format: each uuid.
   */
  sessionIds: string[];
  /** What it did, counted. */
  counts: NightWeavingCounts;
  /** The weaver's private journal entry for the night, also woven as a reflection thread. */
  dreamLog: string | null;
  /**
   * The reflection thread the dream log was woven as. Null when none was written.
   *
   * Format: uuid.
   */
  dreamLogThreadId: string | null;
  /** What went wrong, when anything did. Null otherwise. */
  error: string | null;
  /** The tokens the night spent, one entry per model call. */
  tokenUsage: InteractionProcessTokenUsage[];
  /**
   * The id of the tenant it belongs to.
   *
   * Format: uuid.
   */
  tenantId: string;
  /**
   * The unique id. Use it in `by-id` routes and wherever another object refers to this one.
   *
   * Format: uuid.
   */
  id: string;
  /**
   * When it was created, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateCreated: string;
  /**
   * When it was last changed, in UTC.
   *
   * Format: ISO-8601 date-time, up to 7 fractional digits.
   */
  dateUpdated: string;
}

/** What one night's weaving did. */
export interface NightWeavingCounts {
  /** Conversations (sessions) consolidated. */
  sessionsConsolidated: number;
  /** Episodes woven: summaries of what happened in a conversation. */
  episodesWoven: number;
  /** New threads woven from things said in the conversations that were worth keeping. */
  threadsWoven: number;
  /** Threads strengthened because they were used. */
  threadsTightened: number;
  /** Threads loosened because they were offered and went unused. */
  threadsFrayed: number;
  /** Duplicate threads merged into one that said the same thing. */
  threadsMerged: number;
  /** Outdated threads let go because a newer one replaces them (a "supersedes" tension, acted on). */
  threadsSuperseded: number;
  /** Older dream logs retired, so only the last few nights' stay live (each night's record keeps its own). */
  dreamLogsRetired: number;
  /** Intentions let go because the day they held until has passed. */
  intentionsLapsed: number;
  /** New tensions found between threads. */
  tensionsFound: number;
  /** Themes woven: threads that say what several others have in common, which no single one states. */
  themesWoven: number;
  /** Existing themes reworded to hold what new threads added, instead of being woven again. */
  themesRefined: number;
  /** Tapestry panels woven or rewoven: short portraits of a person or thing. */
  panelsWoven: number;
  /** Codebase patterns refined from what the agents wove about them. */
  patternsRefined: number;
  /** Second-hand threads used often enough tonight to have become the loom's own. */
  threadsMadeOwn: number;
  /** Pairs of threads linked as companions because they were used together. */
  companionsLinked: number;
  /** Threads made searchable by meaning, as well as by their words. */
  threadsEmbedded: number;
}

