/** Creates a connector to one HTTP endpoint. */
export interface OpenApiConnectorCreateRequest {
  /**
   * The HTTP method.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  httpMethod: HttpMethod;
  /**
   * The parameters in the URL's path, one for each `{name}` in `url` (`[]` for none).
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  pathParameters: OpenApiParameterInput[];
  /**
   * The query-string parameters (`[]` for none).
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  queryParameters: OpenApiParameterInput[];
  /**
   * The connector's name, unique within its namespace (under 150 characters).
   *
   * Validation: maxLength: 150; required (empty or whitespace-only strings are rejected).
   */
  name: string;
  /**
   * The endpoint's URL. For an HTTP connector, `{name}` in it marks a path parameter; for an MCP connector, it is the MCP server's URL.
   *
   * Validation: format: url; required (empty or whitespace-only strings are rejected).
   */
  url: string;
  /**
   * What the endpoint does, in a sentence (under 500 characters).
   *
   * Validation: maxLength: 500; required (empty or whitespace-only strings are rejected).
   */
  description: string;
  /**
   * The JSON Schema of the request body, as text. The model's arguments are checked against it before a call is made. Omitted: no body is sent.
   *
   * Sent as-is: the server does not trim it.
   */
  requestSchemaJson?: string | null;
  /**
   * The JSON Schema the endpoint's response must match, as text. Omitted: the response is not checked.
   *
   * Sent as-is: the server does not trim it.
   */
  responseSchemaJson?: string | null;
  /**
   * The kind of credential the endpoint needs. The credential itself is given where a tool uses the connector.
   *
   * Validation: required (empty or whitespace-only strings are rejected).
   */
  authenticationType: ConnectorAuthenticationType;
  /** Whether to replace typographic characters in the response (curly quotes, dashes, bullets, the ellipsis) with plain ones before it is read. Defaults to false. */
  postProcessResponseUnicodeCharacters?: boolean;
}

/** One version of an HTTP (OpenAPI) connector. */
